CREATE OR REPLACE FUNCTION public.fn_rrhh_sincronizar_estado_laboral_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
    v_estado_laboral TEXT;
    v_estado_destino TEXT;
    v_estado_usuario TEXT;
    v_estado_prev_aplicado TEXT;
    v_id_usuario BIGINT;
    v_id_estado_destino INTEGER;
    v_hay_restriccion_manual BOOLEAN;
    v_control public.seg_control_estados_laborales_usuario%ROWTYPE;
BEGIN
    IF NEW.id_estado_trabajador IS NOT DISTINCT FROM OLD.id_estado_trabajador THEN
      RETURN NEW;
    END IF;

    SELECT e.codigo INTO v_estado_laboral
    FROM public.cfg_estados_trabajador e
    WHERE e.id_estado_trabajador=NEW.id_estado_trabajador;

    IF v_estado_laboral NOT IN (
       'ACTIVO','INACTIVO','SUSPENDIDO','CESADO','EN_VERIFICACION'
    ) THEN
      RAISE EXCEPTION 'Estado laboral no reconocido para sincronización';
    END IF;

    SELECT u.id_usuario, eu.codigo
    INTO v_id_usuario,v_estado_usuario
    FROM public.seg_usuarios u
    JOIN public.cfg_estados_usuario eu
      ON eu.id_estado_usuario=u.id_estado_usuario
    WHERE u.id_persona=NEW.id_persona
    FOR UPDATE OF u;

    -- El expediente de un trabajador puede no disponer de cuenta.
    IF NOT FOUND THEN RETURN NEW; END IF;

    SELECT EXISTS(
      SELECT 1 FROM public.seg_restricciones_acceso_manual mr
      WHERE mr.id_usuario=v_id_usuario AND mr.restriccion_activa=TRUE
    ) INTO v_hay_restriccion_manual;

    SELECT * INTO v_control FROM public.seg_control_estados_laborales_usuario
    WHERE id_usuario=v_id_usuario FOR UPDATE;

    IF v_estado_laboral='ACTIVO' THEN
      IF FOUND AND v_control.restriccion_laboral_activa THEN
        -- Reactivar únicamente la cuenta que era ACTIVA antes del bloqueo
        -- y que no fue intervenida independientemente por Seguridad.
        IF v_control.reactivacion_automatica_permitida
          AND NOT v_hay_restriccion_manual
          AND v_estado_usuario=v_control.estado_usuario_aplicado
          AND public.fn_seguridad_acceso_laboral_permitido(NEW.id_persona)
          AND EXISTS (
            SELECT 1 FROM public.seg_usuarios_roles ur
            JOIN public.seg_roles r ON r.id_rol=ur.id_rol
            WHERE ur.id_usuario=v_id_usuario
              AND ur.activo=TRUE AND r.activo=TRUE
          )
        THEN
          SELECT id_estado_usuario INTO v_id_estado_destino
          FROM public.cfg_estados_usuario
          WHERE codigo='ACTIVO' AND activo=TRUE AND permite_acceso=TRUE;
          IF v_id_estado_destino IS NULL THEN
            RAISE EXCEPTION 'No existe estado ACTIVO de usuario';
          END IF;
          UPDATE public.seg_usuarios
          SET id_estado_usuario=v_id_estado_destino,
              fecha_actualizacion=NOW()
          WHERE id_usuario=v_id_usuario;
        END IF;

        UPDATE public.seg_control_estados_laborales_usuario
        SET restriccion_laboral_activa=FALSE,
            estado_laboral='ACTIVO',
            fecha_actualizacion=NOW()
        WHERE id_usuario=v_id_usuario;
      END IF;
      RETURN NEW;
    END IF;

    v_estado_destino := CASE v_estado_laboral
      WHEN 'SUSPENDIDO' THEN 'SUSPENDIDO'
      WHEN 'EN_VERIFICACION' THEN 'SUSPENDIDO'
      ELSE 'INACTIVO'
    END;

    IF NOT FOUND OR NOT v_control.restriccion_laboral_activa THEN
      INSERT INTO public.seg_control_estados_laborales_usuario (
        id_usuario,id_trabajador,estado_usuario_anterior,
        estado_usuario_aplicado,estado_laboral,
        reactivacion_automatica_permitida,restriccion_laboral_activa,
        fecha_inicio,fecha_actualizacion
      ) VALUES (
        v_id_usuario,NEW.id_trabajador,v_estado_usuario,NULL,
        v_estado_laboral,
        v_estado_usuario='ACTIVO' AND NOT v_hay_restriccion_manual,
        TRUE,NOW(),NOW()
      )
      ON CONFLICT(id_usuario) DO UPDATE
      SET id_trabajador=EXCLUDED.id_trabajador,
          estado_usuario_anterior=EXCLUDED.estado_usuario_anterior,
          estado_usuario_aplicado=NULL,
          estado_laboral=EXCLUDED.estado_laboral,
          reactivacion_automatica_permitida=EXCLUDED.reactivacion_automatica_permitida,
          restriccion_laboral_activa=TRUE,
          fecha_inicio=NOW(),
          fecha_actualizacion=NOW();

      v_estado_prev_aplicado := NULL;
    ELSE
      v_estado_prev_aplicado := v_control.estado_usuario_aplicado;
      UPDATE public.seg_control_estados_laborales_usuario
      SET estado_laboral=v_estado_laboral,fecha_actualizacion=NOW()
      WHERE id_usuario=v_id_usuario;
    END IF;

    -- No reemplazar el motivo de una cuenta bloqueada por Seguridad,
    -- ni sobreescribir desactivaciones manuales.
    IF NOT v_hay_restriccion_manual
       AND (
         v_estado_usuario='ACTIVO'
         OR (v_estado_prev_aplicado IS NOT NULL
              AND v_estado_usuario=v_estado_prev_aplicado)
       )
    THEN
      SELECT id_estado_usuario INTO v_id_estado_destino
      FROM public.cfg_estados_usuario
      WHERE codigo=v_estado_destino AND activo=TRUE
        AND permite_acceso=FALSE;

      IF v_id_estado_destino IS NULL THEN
        RAISE EXCEPTION 'No existe estado restringido % de usuario',
          v_estado_destino;
      END IF;

      UPDATE public.seg_usuarios
      SET id_estado_usuario=v_id_estado_destino,
          fecha_actualizacion=NOW()
      WHERE id_usuario=v_id_usuario
        AND id_estado_usuario IS DISTINCT FROM v_id_estado_destino;

      UPDATE public.seg_control_estados_laborales_usuario
      SET estado_usuario_aplicado=v_estado_destino,
          fecha_actualizacion=NOW()
      WHERE id_usuario=v_id_usuario;
    END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_actualizar_persona_expediente(IN p_id_actor bigint, IN p_id_persona bigint, IN p_personal jsonb, OUT p_campos text[], OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
 v_p public.core_personas%ROWTYPE;
 v_doc public.core_personas_documentos%ROWTYPE;
 v_contacto public.core_personas_contactos%ROWTYPE;
 v_dir public.core_personas_direcciones%ROWTYPE;
 v_email_tipo integer; v_tel_tipo integer;
 v_nombre text;v_pat text;v_mat text;v_nac date;
 v_correo text;v_actual_correo text;
 v_tel text;v_tel_id bigint;
 v_dir_nueva text;v_ref text;v_dep text;v_prov text;v_dist text;
BEGIN
 p_campos:=ARRAY[]::text[];p_estado:='OK';p_mensaje:='Información personal validada.';
 IF p_personal IS NULL THEN RETURN; END IF;
 IF jsonb_typeof(p_personal) IS DISTINCT FROM 'object'
    OR p_id_actor IS NULL OR NOT public.fn_usuario_tiene_permiso_seguridad(p_id_actor,'hr.edit')
    OR NOT EXISTS(SELECT 1 FROM public.rrhh_trabajadores WHERE id_persona=p_id_persona)
 THEN p_estado:='DENEGADO';p_mensaje:='Información personal o autorización inválida.';RETURN;END IF;
 SELECT * INTO v_p FROM public.core_personas WHERE id_persona=p_id_persona AND activo FOR UPDATE;
 IF NOT FOUND THEN p_estado:='PERSONA_INVALIDA';p_mensaje:='Persona inactiva o inexistente.';RETURN;END IF;
 IF p_personal ? 'idPersona' AND
    NULLIF(BTRIM(p_personal->>'idPersona'),'')::bigint IS DISTINCT FROM p_id_persona
 THEN p_estado:='PERSONA_NO_COINCIDE';p_mensaje:='No se puede sustituir la identidad del trabajador.';RETURN;END IF;
 SELECT * INTO v_doc FROM public.core_personas_documentos
 WHERE id_persona=p_id_persona AND activo AND principal ORDER BY id_persona_documento DESC LIMIT 1;
 IF NOT FOUND THEN p_estado:='DOCUMENTO_INVALIDO';p_mensaje:='Falta el documento principal.';RETURN;END IF;
 IF (p_personal ? 'idTipoDocumento' AND
     NULLIF(BTRIM(p_personal->>'idTipoDocumento'),'')::integer IS DISTINCT FROM v_doc.id_tipo_documento)
   OR (p_personal ? 'numeroDocumento' AND
       UPPER(NULLIF(BTRIM(p_personal->>'numeroDocumento'),'')) IS DISTINCT FROM UPPER(BTRIM(v_doc.numero_documento)))
 THEN p_estado:='CORRECCION_DOCUMENTAL_REQUERIDA';
      p_mensaje:='El documento requiere evidencia y autorización.';RETURN;END IF;
 v_nombre:=CASE WHEN p_personal ? 'nombres' THEN NULLIF(BTRIM(p_personal->>'nombres'),'') ELSE v_p.nombres END;
 v_pat:=CASE WHEN p_personal ? 'apellidoPaterno' THEN NULLIF(BTRIM(p_personal->>'apellidoPaterno'),'') ELSE v_p.apellido_paterno END;
 v_mat:=CASE WHEN p_personal ? 'apellidoMaterno' THEN NULLIF(BTRIM(p_personal->>'apellidoMaterno'),'') ELSE v_p.apellido_materno END;
 v_nac:=CASE WHEN p_personal ? 'fechaNacimiento' THEN NULLIF(BTRIM(p_personal->>'fechaNacimiento'),'')::date ELSE v_p.fecha_nacimiento END;
 IF v_nombre IS NULL OR LENGTH(v_nombre)>120 OR LENGTH(COALESCE(v_pat,''))>80 OR LENGTH(COALESCE(v_mat,''))>80
    OR v_nac>CURRENT_DATE
 THEN p_estado:='DATOS_INVALIDOS';p_mensaje:='Datos personales inválidos.';RETURN;END IF;
 IF p_personal ? 'correoElectronico' THEN
  SELECT id_tipo_contacto INTO v_email_tipo FROM public.cfg_tipos_contacto WHERE codigo='EMAIL' AND activo;
  IF v_email_tipo IS NULL THEN p_estado:='CONFIGURACION_INVALIDA';p_mensaje:='No se configuró EMAIL.';RETURN;END IF;
  SELECT LOWER(BTRIM(valor)) INTO v_actual_correo FROM public.core_personas_contactos
   WHERE id_persona=p_id_persona AND id_tipo_contacto=v_email_tipo AND activo AND principal
   ORDER BY id_persona_contacto DESC LIMIT 1;
  v_correo:=LOWER(NULLIF(BTRIM(p_personal->>'correoElectronico'),''));
  IF v_correo IS DISTINCT FROM v_actual_correo THEN
   p_estado:='EMAIL_VERIFICACION_REQUERIDA';
   p_mensaje:='El correo se cambia mediante un enlace de confirmación enviado al nuevo correo.';
   RETURN;
  END IF;
 END IF;
 IF p_personal ? 'telefono' THEN
  SELECT id_tipo_contacto INTO v_tel_tipo FROM public.cfg_tipos_contacto WHERE codigo='CELULAR' AND activo;
  IF v_tel_tipo IS NULL THEN p_estado:='CONFIGURACION_INVALIDA';p_mensaje:='No se configuró CELULAR.';RETURN;END IF;
  SELECT * INTO v_contacto FROM public.core_personas_contactos
   WHERE id_persona=p_id_persona AND id_tipo_contacto=v_tel_tipo AND activo AND principal
   ORDER BY id_persona_contacto DESC LIMIT 1;
  v_tel:=NULLIF(BTRIM(p_personal->>'telefono'),'');
  IF v_tel IS NOT NULL AND
    (LENGTH(v_tel)>25 OR v_tel !~ '^[+0-9() -]+$'
       OR LENGTH(REGEXP_REPLACE(v_tel,'[^0-9]','','g'))<6)
  THEN p_estado:='TELEFONO_INVALIDO';p_mensaje:='Teléfono inválido.';RETURN;END IF;
 END IF;
 IF p_personal ?| ARRAY['direccion','referencia','departamento','provincia','distrito'] THEN
  SELECT * INTO v_dir FROM public.core_personas_direcciones
   WHERE id_persona=p_id_persona AND tipo='DOMICILIO' AND activo AND principal
   ORDER BY id_persona_direccion DESC LIMIT 1;
  v_dir_nueva:=CASE WHEN p_personal ? 'direccion' THEN NULLIF(BTRIM(p_personal->>'direccion'),'') ELSE v_dir.direccion END;
  v_ref:=CASE WHEN p_personal ? 'referencia' THEN NULLIF(BTRIM(p_personal->>'referencia'),'') ELSE v_dir.referencia END;
  v_dep:=CASE WHEN p_personal ? 'departamento' THEN NULLIF(BTRIM(p_personal->>'departamento'),'') ELSE v_dir.departamento END;
  v_prov:=CASE WHEN p_personal ? 'provincia' THEN NULLIF(BTRIM(p_personal->>'provincia'),'') ELSE v_dir.provincia END;
  v_dist:=CASE WHEN p_personal ? 'distrito' THEN NULLIF(BTRIM(p_personal->>'distrito'),'') ELSE v_dir.distrito END;
  IF v_dir_nueva IS NULL OR LENGTH(v_dir_nueva)>255
    OR v_dep IS NULL OR LENGTH(v_dep)>100
    OR v_prov IS NULL OR LENGTH(v_prov)>100
    OR v_dist IS NULL OR LENGTH(v_dist)>100
    OR LENGTH(COALESCE(v_ref,''))>255
  THEN p_estado:='DOMICILIO_INVALIDO';p_mensaje:='Domicilio incompleto o inválido.';RETURN;END IF;
 END IF;
 -- Escrituras: todo en la misma transacción que el cambio laboral.
 IF ROW(v_p.nombres,v_p.apellido_paterno,v_p.apellido_materno,v_p.fecha_nacimiento)
   IS DISTINCT FROM ROW(v_nombre,v_pat,v_mat,v_nac)
 THEN
  UPDATE public.core_personas SET nombres=v_nombre,apellido_paterno=v_pat,
    apellido_materno=v_mat,fecha_nacimiento=v_nac,fecha_actualizacion=NOW()
   WHERE id_persona=p_id_persona;
  p_campos:=ARRAY_APPEND(p_campos,'informacionPersonal');
 END IF;
 IF p_personal ? 'telefono' AND v_tel IS DISTINCT FROM v_contacto.valor THEN
  SELECT id_persona_contacto INTO v_tel_id FROM public.core_personas_contactos
    WHERE id_persona=p_id_persona AND id_tipo_contacto=v_tel_tipo AND valor=v_tel
    ORDER BY id_persona_contacto DESC LIMIT 1;
  UPDATE public.core_personas_contactos SET principal=FALSE,activo=FALSE,fecha_actualizacion=NOW()
    WHERE id_persona=p_id_persona AND id_tipo_contacto=v_tel_tipo AND principal AND activo;
  IF v_tel IS NOT NULL THEN
    IF v_tel_id IS NOT NULL THEN
       UPDATE public.core_personas_contactos SET principal=TRUE,activo=TRUE,verificado=FALSE,
         fecha_actualizacion=NOW() WHERE id_persona_contacto=v_tel_id;
    ELSE
       INSERT INTO public.core_personas_contactos
         (id_persona,id_tipo_contacto,valor,principal,verificado,activo,permite_notificaciones)
       VALUES(p_id_persona,v_tel_tipo,v_tel,TRUE,FALSE,TRUE,FALSE);
    END IF;
  END IF;
  p_campos:=ARRAY_APPEND(p_campos,'telefono');
 END IF;
 IF p_personal ?| ARRAY['direccion','referencia','departamento','provincia','distrito'] THEN
  IF v_dir.id_persona_direccion IS NULL THEN
   INSERT INTO public.core_personas_direcciones
     (id_persona,tipo,direccion,referencia,departamento,provincia,distrito,pais,principal,activo)
   VALUES(p_id_persona,'DOMICILIO',v_dir_nueva,v_ref,v_dep,v_prov,v_dist,'Perú',TRUE,TRUE);
   p_campos:=ARRAY_APPEND(p_campos,'domicilio');
  ELSIF ROW(v_dir.direccion,v_dir.referencia,v_dir.departamento,v_dir.provincia,v_dir.distrito)
    IS DISTINCT FROM ROW(v_dir_nueva,v_ref,v_dep,v_prov,v_dist) THEN
   UPDATE public.core_personas_direcciones SET direccion=v_dir_nueva,referencia=v_ref,
     departamento=v_dep,provincia=v_prov,distrito=v_dist,fecha_actualizacion=NOW()
    WHERE id_persona_direccion=v_dir.id_persona_direccion;
   p_campos:=ARRAY_APPEND(p_campos,'domicilio');
  END IF;
 END IF;
 p_estado:='OK';p_mensaje:='Información personal actualizada.';
EXCEPTION
 WHEN unique_violation THEN p_campos:=ARRAY[]::text[];p_estado:='CONFLICTO_UNICIDAD';p_mensaje:='Un registro existente impide duplicar estos datos.';
 WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN
  p_campos:=ARRAY[]::text[];p_estado:='DATOS_INVALIDOS';p_mensaje:='Uno de los datos tiene un formato inválido.';
END;$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_actualizar_trabajador(IN p_id_actor bigint, IN p_id_trabajador bigint, IN p_datos jsonb, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_laboral JSONB;
    v_personal_campos TEXT[];
    v_personal_estado VARCHAR;
    v_personal_mensaje VARCHAR;
    v_trabajador public.rrhh_trabajadores%ROWTYPE;

    v_id_cargo BIGINT;
    v_id_horario BIGINT;
    v_id_vinculo INTEGER;
    v_fecha_ingreso DATE;
    v_fecha_cese DATE;
    v_observaciones TEXT;
    v_motivo_cambio TEXT;

    v_id_estado_nuevo INTEGER;
    v_codigo_estado_actual TEXT;
    v_codigo_estado_nuevo TEXT;
    v_estado_catalogo_activo BOOLEAN;
    v_cambio_estado BOOLEAN := FALSE;
    v_cambio_periodo BOOLEAN := FALSE;

    v_campos_modificados TEXT[] := ARRAY[]::TEXT[];
BEGIN
    p_resultado := NULL;

    -- 1. AUTORIZACIÓN EXISTENTE
    IF p_id_actor IS NULL
       OR NOT public.fn_usuario_tiene_permiso_seguridad(
           p_id_actor, 'hr.edit'
       )
    THEN
        p_estado := 'DENEGADO';
        p_mensaje := 'No tiene permisos para editar trabajadores.';
        RETURN;
    END IF;

    -- 2. VALIDAR Y BLOQUEAR TRABAJADOR
    IF p_id_trabajador IS NULL OR p_id_trabajador <= 0 THEN
        p_estado := 'ID_INVALIDO';
        p_mensaje := 'El identificador del trabajador es inválido.';
        RETURN;
    END IF;

    SELECT * INTO v_trabajador
    FROM public.rrhh_trabajadores
    WHERE id_trabajador = p_id_trabajador
    FOR UPDATE;

    IF NOT FOUND THEN
        p_estado := 'NO_ENCONTRADO';
        p_mensaje := 'El trabajador solicitado no existe.';
        RETURN;
    END IF;


    -- Protección de Gerencia: RRHH no puede editar al Gerente General.
    -- El titular solo puede modificar información personal autorizada.
    IF (
        EXISTS (
          SELECT 1 FROM public.rrhh_cargos c
          WHERE c.id_cargo=v_trabajador.id_cargo AND c.codigo='GERENTE_GENERAL'
        )
        OR EXISTS (
          SELECT 1 FROM public.seg_usuarios u
          JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo=TRUE
          JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo=TRUE
          WHERE u.id_persona=v_trabajador.id_persona AND r.codigo='GERENCIA'
        )
    ) THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.seg_usuarios u
          WHERE u.id_usuario=p_id_actor AND u.id_persona=v_trabajador.id_persona
        ) THEN
          p_estado:='USUARIO_PROTEGIDO';
          p_mensaje:='Solo el Gerente General puede modificar su información personal.';
          RETURN;
        END IF;
        IF p_datos ? 'informacionLaboral' THEN
          p_estado:='USUARIO_PROTEGIDO';
          p_mensaje:='El Gerente General no puede modificar su propio estado ni datos laborales.';
          RETURN;
        END IF;
    END IF;

    -- 3. VALIDAR FORMULARIO EXISTENTE
    IF p_datos IS NULL
       OR JSONB_TYPEOF(p_datos) IS DISTINCT FROM 'object'
       OR (p_datos ? 'informacionLaboral'
           AND JSONB_TYPEOF(p_datos->'informacionLaboral') IS DISTINCT FROM 'object')
       OR NOT (p_datos ? 'informacionLaboral' OR p_datos ? 'informacionPersonal')
    THEN
        p_estado := 'DATOS_INVALIDOS';
        p_mensaje := 'Indique informacionPersonal o informacionLaboral válidas.';
        RETURN;
    END IF;

    IF p_datos ? 'informacionPersonal'
       AND JSONB_TYPEOF(p_datos->'informacionPersonal') IS DISTINCT FROM 'object'
    THEN
        p_estado := 'DATOS_INVALIDOS';
        p_mensaje := 'La información personal debe ser un objeto JSON.';
        RETURN;
    END IF;

    v_laboral := JSONB_BUILD_OBJECT(
        'idCargo', v_trabajador.id_cargo,
        'idHorario', v_trabajador.id_horario,
        'idTipoVinculoLaboral', v_trabajador.id_tipo_vinculo_laboral,
        'fechaIngreso', v_trabajador.fecha_ingreso,
        'observaciones', v_trabajador.observaciones
    ) || COALESCE(p_datos->'informacionLaboral', '{}'::JSONB);

    v_id_cargo := NULLIF(BTRIM(v_laboral->>'idCargo'), '')::BIGINT;
    v_id_horario := NULLIF(BTRIM(v_laboral->>'idHorario'), '')::BIGINT;
    v_id_vinculo := NULLIF(
        BTRIM(v_laboral->>'idTipoVinculoLaboral'), ''
    )::INTEGER;
    v_fecha_ingreso := NULLIF(
        v_laboral->>'fechaIngreso', ''
    )::DATE;
    v_observaciones := NULLIF(
        BTRIM(v_laboral->>'observaciones'), ''
    );
    v_motivo_cambio := NULLIF(
        BTRIM(v_laboral->>'motivoCambioEstado'), ''
    );

    -- Compatibilidad: si la edición actual no incluye el estado,
    -- se conserva exactamente el estado existente.
    v_id_estado_nuevo := v_trabajador.id_estado_trabajador;
    IF v_laboral ? 'idEstadoTrabajador' THEN
        IF NULLIF(BTRIM(v_laboral->>'idEstadoTrabajador'), '') IS NULL THEN
            p_estado := 'ESTADO_INVALIDO';
            p_mensaje := 'Debe indicar un estado laboral válido.';
            RETURN;
        END IF;
        v_id_estado_nuevo := (
            BTRIM(v_laboral->>'idEstadoTrabajador')
        )::INTEGER;
    END IF;

    v_cambio_estado := v_trabajador.id_estado_trabajador
                       IS DISTINCT FROM v_id_estado_nuevo;

    -- 4. CAMPOS OBLIGATORIOS ORIGINALES
    IF v_id_cargo IS NULL
       OR v_id_vinculo IS NULL
       OR v_fecha_ingreso IS NULL
    THEN
        p_estado := 'CAMPOS_OBLIGATORIOS';
        p_mensaje := 'Complete los datos laborales obligatorios.';
        RETURN;
    END IF;

    -- 5. VALIDAR CARGO Y ÁREA
    PERFORM 1
    FROM public.rrhh_cargos c
    JOIN public.rrhh_areas a ON a.id_area = c.id_area
    WHERE c.id_cargo = v_id_cargo
      AND c.activo = TRUE
      AND a.activo = TRUE;

    IF NOT FOUND THEN
        p_estado := 'CARGO_INVALIDO';
        p_mensaje := 'El cargo o su área no están activos.';
        RETURN;
    END IF;

    -- 6. VALIDAR HORARIO OPCIONAL
    IF v_id_horario IS NOT NULL THEN
        PERFORM 1
        FROM public.rrhh_horarios
        WHERE id_horario = v_id_horario AND activo = TRUE;

        IF NOT FOUND THEN
            p_estado := 'HORARIO_INVALIDO';
            p_mensaje := 'El horario no está disponible.';
            RETURN;
        END IF;
    END IF;

    -- 7. VALIDAR VÍNCULO LABORAL
    PERFORM 1
    FROM public.cfg_tipos_vinculo_laboral
    WHERE id_tipo_vinculo_laboral = v_id_vinculo AND activo = TRUE;

    IF NOT FOUND THEN
        p_estado := 'VINCULO_INVALIDO';
        p_mensaje := 'El vínculo laboral no está disponible.';
        RETURN;
    END IF;

    -- 8. LAS FECHAS DE CESE DEPENDEN DEL ESTADO RESULTANTE.
    -- Se validan después de identificar los códigos de catálogo.

    -- 9. VALIDACIÓN DE CAMBIO DE ESTADO
    SELECT e.codigo
      INTO v_codigo_estado_actual
    FROM public.cfg_estados_trabajador e
    WHERE e.id_estado_trabajador = v_trabajador.id_estado_trabajador;

    IF NOT FOUND THEN
        p_estado := 'ESTADO_INVALIDO';
        p_mensaje := 'El estado laboral actual requiere revisión.';
        RETURN;
    END IF;

    IF v_cambio_estado THEN
        -- La edición ordinaria nunca puede crear ni resolver por sí misma
        -- un estado EN_VERIFICACION; se utilizará el flujo documental.
        IF v_codigo_estado_actual = 'EN_VERIFICACION' THEN
            p_estado := 'VERIFICACION_DOCUMENTAL_PENDIENTE';
            p_mensaje := 'El estado de verificación se resuelve mediante su solicitud documental.';
            RETURN;
        END IF;

        SELECT e.codigo, e.activo
          INTO v_codigo_estado_nuevo, v_estado_catalogo_activo
        FROM public.cfg_estados_trabajador e
        WHERE e.id_estado_trabajador = v_id_estado_nuevo;

        IF NOT FOUND
           OR v_estado_catalogo_activo IS DISTINCT FROM TRUE
           OR v_codigo_estado_nuevo NOT IN (
               'ACTIVO', 'INACTIVO', 'SUSPENDIDO', 'CESADO'
           )
        THEN
            p_estado := 'ESTADO_INVALIDO';
            p_mensaje := 'El estado seleccionado no puede asignarse desde la edición laboral.';
            RETURN;
        END IF;

        -- Protege las cuentas de GERENCIA/ADMINISTRADOR y evita que
        -- un actor bloquee su propio expediente por esta vía.
        -- Se aplica al cambio hacia cualquier estado para impedir
        -- que actores sin atribuciones gestionen cuentas protegidas.
        IF NOT COALESCE(
            public.fn_seguridad_puede_bloquear_persona(
                p_id_actor, v_trabajador.id_persona
            ), FALSE
        ) THEN
            p_estado := 'USUARIO_PROTEGIDO';
            p_mensaje := 'No tiene autorización para modificar el estado de esta cuenta protegida.';
            RETURN;
        END IF;
    END IF;


    -- La reincorporación de un trabajador cesado requiere aprobación del
    -- Administrador, nunca un cambio manual desde Edición.
    IF v_codigo_estado_actual='CESADO' AND v_cambio_estado THEN
      p_estado:='ESTADO_INVALIDO';
      p_mensaje:='La reincorporación de un trabajador cesado requiere aprobación del Administrador.';
      RETURN;
    END IF;

    -- Las suspensiones necesitan un intervalo de inicio y fin validado.
    -- Su apertura se gestionará por el flujo específico de suspensión.
    IF v_cambio_estado AND v_codigo_estado_nuevo='SUSPENDIDO' THEN
      p_estado:='ESTADO_INVALIDO';
      p_mensaje:='La suspensión requiere un período registrado en el flujo específico.';
      RETURN;
    END IF;


    -- No permitir un cese sin registro y notificación administrativa
    -- hasta integrar el flujo validado de Cese/Reincorporación.
    IF v_cambio_estado AND v_codigo_estado_nuevo='CESADO' THEN
      p_estado:='ESTADO_INVALIDO';
      p_mensaje:='El cese requiere el flujo con registro y notificación al Administrador.';
      RETURN;
    END IF;

    -- 10. FECHAS Y PERIODOS LABORALES
    v_codigo_estado_nuevo := COALESCE(
        v_codigo_estado_nuevo, v_codigo_estado_actual
    );
    v_fecha_cese := v_trabajador.fecha_cese;

    IF v_codigo_estado_actual = 'CESADO'
       AND v_cambio_estado
       AND v_codigo_estado_nuevo <> 'ACTIVO'
    THEN
        p_estado := 'ESTADO_INVALIDO';
        p_mensaje := 'Un trabajador cesado solo puede reincorporarse en estado ACTIVO.';
        RETURN;
    END IF;

    IF v_codigo_estado_nuevo = 'CESADO' THEN
        -- Un cese nuevo exige fecha expresa; uno existente conserva su fecha
        -- cuando se editan otros datos sin suministrar fechaCese.
        IF v_laboral ? 'fechaCese' THEN
            v_fecha_cese := NULLIF(BTRIM(v_laboral->>'fechaCese'), '')::DATE;
        ELSIF v_codigo_estado_actual <> 'CESADO' THEN
            v_fecha_cese := NULL;
        END IF;

        IF v_fecha_cese IS NULL THEN
            p_estado := 'FECHAS_INVALIDAS';
            p_mensaje := 'Al cesar al trabajador debe indicar fechaCese.';
            RETURN;
        END IF;

        IF v_fecha_cese < v_fecha_ingreso
           OR v_fecha_cese > CURRENT_DATE
        THEN
            p_estado := 'FECHAS_INVALIDAS';
            p_mensaje := 'La fecha de cese debe estar entre el ingreso y la fecha actual.';
            RETURN;
        END IF;

    ELSE
        -- Un estado no CESADO nunca admite fecha de cese nueva.
        IF NULLIF(BTRIM(v_laboral->>'fechaCese'), '') IS NOT NULL THEN
            p_estado := 'FECHAS_INVALIDAS';
            p_mensaje := 'La fecha de cese solo corresponde al estado CESADO.';
            RETURN;
        END IF;

        IF v_codigo_estado_actual = 'CESADO'
           AND v_codigo_estado_nuevo = 'ACTIVO' THEN
            -- No sobrescribir el periodo terminado con su fecha anterior.
            -- El periodo que terminó quedará almacenado en el historial.
            IF v_trabajador.fecha_cese IS NULL
               OR v_fecha_ingreso <= v_trabajador.fecha_cese
            THEN
                p_estado := 'FECHAS_INVALIDAS';
                p_mensaje := 'La reincorporación exige nueva fechaIngreso posterior al último cese.';
                RETURN;
            END IF;
        END IF;

        -- La fecha de cese se limpia al reincorporar a un trabajador.
        IF v_codigo_estado_actual = 'CESADO'
           AND v_codigo_estado_nuevo = 'ACTIVO'
        THEN
            v_fecha_cese := NULL;
        ELSIF v_trabajador.fecha_cese IS NOT NULL THEN
            -- No borrar silenciosamente datos anómalos en otros estados.
            p_estado := 'FECHAS_INVALIDAS';
            p_mensaje := 'El expediente conserva una fecha de cese incompatible; requiere revisión.';
            RETURN;
        END IF;
    END IF;

    v_cambio_periodo :=
        v_trabajador.fecha_ingreso IS DISTINCT FROM v_fecha_ingreso
        OR v_trabajador.fecha_cese IS DISTINCT FROM v_fecha_cese;

    -- 11. DETECTAR CAMBIOS, CONSERVANDO LOS CAMPOS ORIGINALES
    IF v_trabajador.id_cargo IS DISTINCT FROM v_id_cargo THEN
        v_campos_modificados := ARRAY_APPEND(v_campos_modificados, 'idCargo');
    END IF;

    IF v_trabajador.id_horario IS DISTINCT FROM v_id_horario THEN
        v_campos_modificados := ARRAY_APPEND(v_campos_modificados, 'idHorario');
    END IF;

    IF v_trabajador.id_tipo_vinculo_laboral IS DISTINCT FROM v_id_vinculo THEN
        v_campos_modificados := ARRAY_APPEND(v_campos_modificados, 'idTipoVinculoLaboral');
    END IF;

    IF v_trabajador.fecha_ingreso IS DISTINCT FROM v_fecha_ingreso THEN
        v_campos_modificados := ARRAY_APPEND(v_campos_modificados, 'fechaIngreso');
    END IF;

    IF v_trabajador.observaciones IS DISTINCT FROM v_observaciones THEN
        v_campos_modificados := ARRAY_APPEND(v_campos_modificados, 'observaciones');
    END IF;

    IF v_trabajador.fecha_cese IS DISTINCT FROM v_fecha_cese THEN
        v_campos_modificados := ARRAY_APPEND(v_campos_modificados, 'fechaCese');
    END IF;

    IF v_cambio_estado THEN
        v_campos_modificados := ARRAY_APPEND(v_campos_modificados, 'idEstadoTrabajador');
    END IF;


    -- Actualizar datos personales sin saltarse Seguridad ni perder la auditoría.
    IF p_datos ? 'informacionPersonal' THEN
        CALL public.sp_rrhh_actualizar_persona_expediente(
            p_id_actor, v_trabajador.id_persona,
            p_datos->'informacionPersonal',
            v_personal_campos, v_personal_estado, v_personal_mensaje
        );
        IF v_personal_estado IS DISTINCT FROM 'OK' THEN
            p_resultado := NULL;
            p_estado := v_personal_estado;
            p_mensaje := v_personal_mensaje;
            RETURN;
        END IF;
        v_campos_modificados := v_campos_modificados ||
            COALESCE(v_personal_campos, ARRAY[]::TEXT[]);
    END IF;

    -- 12. ACTUALIZAR EXPEDIENTE. El trigger ya instalado revoca sesiones
    -- e incrementa version_sesiones dentro de ESTA MISMA TRANSACCIÓN.
    UPDATE public.rrhh_trabajadores
    SET id_cargo = v_id_cargo,
        id_horario = v_id_horario,
        id_tipo_vinculo_laboral = v_id_vinculo,
        fecha_ingreso = v_fecha_ingreso,
        fecha_cese = v_fecha_cese,
        observaciones = v_observaciones,
        id_estado_trabajador = v_id_estado_nuevo
    WHERE id_trabajador = p_id_trabajador;

    -- 13. HISTORIAL LABORAL: estado o fechas cambiadas.
    -- Misma transacción que el UPDATE anterior y su trigger de revocación.
    IF v_cambio_estado OR v_cambio_periodo THEN
        INSERT INTO public.rrhh_trabajadores_historial_laboral (
            id_trabajador,
            id_estado_anterior,
            id_estado_nuevo,
            fecha_ingreso_anterior,
            fecha_ingreso_nueva,
            fecha_cese_anterior,
            fecha_cese_nueva,
            motivo,
            id_usuario_actor
        ) VALUES (
            v_trabajador.id_trabajador,
            v_trabajador.id_estado_trabajador,
            v_id_estado_nuevo,
            v_trabajador.fecha_ingreso,
            v_fecha_ingreso,
            v_trabajador.fecha_cese,
            v_fecha_cese,
            v_motivo_cambio,
            p_id_actor
        );
    END IF;

    -- 14. AUDITORÍA CENTRALIZADA
    IF CARDINALITY(v_campos_modificados) > 0 THEN
        PERFORM public.sp_registrar_auditoria(
            p_id_actor,
            'RRHH'::VARCHAR,
            'ACTUALIZAR'::VARCHAR,
            'rrhh_trabajadores'::VARCHAR,
            p_id_trabajador::VARCHAR,
            'EXITOSO'::VARCHAR,
            'Actualización integral del expediente del trabajador.'::VARCHAR,
            JSONB_BUILD_OBJECT(
                'idPersona', v_trabajador.id_persona,
                'camposModificados', v_campos_modificados,
                'idCargoAnterior', v_trabajador.id_cargo,
                'idCargoNuevo', v_id_cargo,
                'idVinculoAnterior', v_trabajador.id_tipo_vinculo_laboral,
                'idVinculoNuevo', v_id_vinculo,
                'idEstadoAnterior', v_trabajador.id_estado_trabajador,
                'idEstadoNuevo', v_id_estado_nuevo,
                'fechaIngresoAnterior', v_trabajador.fecha_ingreso,
                'fechaIngresoNueva', v_fecha_ingreso,
                'fechaCeseAnterior', v_trabajador.fecha_cese,
                'fechaCeseNueva', v_fecha_cese,
                'codigoEstadoAnterior', v_codigo_estado_actual,
                'codigoEstadoNuevo',
                    CASE WHEN v_cambio_estado
                         THEN v_codigo_estado_nuevo
                         ELSE v_codigo_estado_actual END
            )
        );
    END IF;

    -- 15. RESPUESTA
    p_resultado := JSONB_BUILD_OBJECT(
        'idTrabajador', v_trabajador.id_trabajador,
        'idPersona', v_trabajador.id_persona,
        'codigo', v_trabajador.codigo,
        'idEstadoTrabajador', v_id_estado_nuevo,
        'fechaCese', v_fecha_cese,
        'camposModificados', v_campos_modificados
    );

    p_estado := 'OK';
    p_mensaje := 'Expediente actualizado correctamente.';

EXCEPTION
    WHEN unique_violation THEN
        p_resultado := NULL;
        p_estado := 'CONFLICTO_UNICIDAD';
        p_mensaje := 'Un registro existente impide aplicar estos cambios.';
    WHEN invalid_text_representation
      OR invalid_datetime_format
      OR datetime_field_overflow
      OR numeric_value_out_of_range
    THEN
        p_resultado := NULL;
        p_estado := 'DATOS_INVALIDOS';
        p_mensaje := 'Uno o más identificadores o fechas tienen formato inválido.';
END;
$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_cesar_trabajador(IN p_id_actor bigint, IN p_id_trabajador bigint, IN p_fecha_cese date, IN p_motivo text, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
 v_t public.rrhh_trabajadores%ROWTYPE;
 v_estado_actual TEXT;
 v_estado_cesado INTEGER;
 v_id_historial BIGINT;
 v_nombre TEXT;
 v_tipo_notificacion INTEGER;
 v_notificaciones INTEGER;
BEGIN
 p_resultado:=NULL; p_estado:='DATOS_INVALIDOS';
 p_mensaje:='Datos de cese inválidos.';
 IF p_id_actor IS NULL OR p_id_trabajador IS NULL OR p_id_trabajador<=0
    OR NOT COALESCE(public.fn_usuario_tiene_permiso_seguridad(p_id_actor,'hr.edit'),FALSE)
 THEN
   p_estado:='DENEGADO'; p_mensaje:='No tiene permisos para cesar trabajadores.'; RETURN;
 END IF;
 IF p_fecha_cese IS NULL OR LENGTH(COALESCE(BTRIM(p_motivo),'')) NOT BETWEEN 10 AND 1000 THEN
   p_estado:='DATOS_INVALIDOS';
   p_mensaje:='Indique fecha de cese y motivo de 10 a 1000 caracteres.';RETURN;
 END IF;

 SELECT * INTO v_t FROM public.rrhh_trabajadores
 WHERE id_trabajador=p_id_trabajador FOR UPDATE;
 IF NOT FOUND THEN
  p_estado:='NO_ENCONTRADO';p_mensaje:='Trabajador no encontrado.'; RETURN;
 END IF;

 IF EXISTS (SELECT 1 FROM public.rrhh_cargos c
            WHERE c.id_cargo=v_t.id_cargo AND c.codigo='GERENTE_GENERAL')
   OR EXISTS (SELECT 1 FROM public.seg_usuarios u
     JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
     JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo
     WHERE u.id_persona=v_t.id_persona AND r.codigo='GERENCIA')
   OR NOT COALESCE(public.fn_seguridad_puede_bloquear_persona(
     p_id_actor,v_t.id_persona),FALSE)
 THEN
    p_estado:='USUARIO_PROTEGIDO';
    p_mensaje:='No puede cesar a un trabajador protegido.';
    RETURN;
 END IF;

 SELECT codigo INTO v_estado_actual FROM public.cfg_estados_trabajador
 WHERE id_estado_trabajador=v_t.id_estado_trabajador;
 IF v_estado_actual NOT IN ('ACTIVO','INACTIVO','SUSPENDIDO') THEN
   p_estado:='ESTADO_INVALIDO';
   p_mensaje:='No se permite cesar desde el estado laboral actual.';
   RETURN;
 END IF;
 IF p_fecha_cese < v_t.fecha_ingreso OR p_fecha_cese > CURRENT_DATE THEN
   p_estado:='FECHAS_INVALIDAS';
   p_mensaje:='Fecha de cese fuera del período laboral.';
   RETURN;
 END IF;

 SELECT id_estado_trabajador INTO v_estado_cesado
 FROM public.cfg_estados_trabajador WHERE codigo='CESADO' AND activo=TRUE;
 SELECT id_tipo_notificacion INTO v_tipo_notificacion
 FROM public.cfg_tipos_notificacion WHERE codigo='GENERAL' AND activo=TRUE;
 IF v_estado_cesado IS NULL OR v_tipo_notificacion IS NULL THEN
   p_estado:='CONFIGURACION_INVALIDA';
   p_mensaje:='Faltan estados o tipo de notificación.';
   RETURN;
 END IF;
 IF NOT EXISTS(
   SELECT 1 FROM public.seg_usuarios u
   JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
   JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo AND r.codigo='ADMINISTRADOR'
   JOIN public.cfg_estados_usuario eu ON eu.id_estado_usuario=u.id_estado_usuario
   WHERE eu.codigo='ACTIVO' AND eu.permite_acceso=TRUE
 ) THEN
   p_estado:='SIN_ADMINISTRADOR';
   p_mensaje:='No hay administrador activo para notificar el cese.';
   RETURN;
 END IF;

 -- Un cese cancela suspensiones futuras o vigentes.
 UPDATE public.rrhh_suspensiones_laborales
 SET estado='CANCELADA',fecha_cancelacion=NOW(),
     error_ultimo='Cancelada por cese laboral.',
     fecha_actualizacion=NOW()
 WHERE id_trabajador=p_id_trabajador AND estado IN ('PROGRAMADA','VIGENTE');

 UPDATE public.rrhh_trabajadores
 SET id_estado_trabajador=v_estado_cesado,
     fecha_cese=p_fecha_cese
 WHERE id_trabajador=p_id_trabajador;

 INSERT INTO public.rrhh_trabajadores_historial_laboral(
   id_trabajador,id_estado_anterior,id_estado_nuevo,
   fecha_ingreso_anterior,fecha_ingreso_nueva,
   fecha_cese_anterior,fecha_cese_nueva,motivo,id_usuario_actor)
 VALUES(
   p_id_trabajador,v_t.id_estado_trabajador,v_estado_cesado,
   v_t.fecha_ingreso,v_t.fecha_ingreso,
   v_t.fecha_cese,p_fecha_cese,BTRIM(p_motivo),p_id_actor
 )
 RETURNING id_historial INTO v_id_historial;

 SELECT CONCAT_WS(' ',p.nombres,p.apellido_paterno,p.apellido_materno)
 INTO v_nombre FROM public.core_personas p WHERE p.id_persona=v_t.id_persona;

 INSERT INTO public.not_notificaciones(
   id_persona,id_tipo_notificacion,titulo,mensaje,url_destino,
   referencia_modulo,referencia_entidad,referencia_id,
   datos_contexto,clave_deduplicacion,id_usuario_generacion
 )
 SELECT DISTINCT
   u.id_persona,v_tipo_notificacion,'Cese de trabajador',
   LEFT('El trabajador '||v_nombre||' ('||v_t.codigo||') cesó el día '||
    TO_CHAR(p_fecha_cese,'DD/MM/YYYY')||'.',1000),
   '/trabajadores',
   'RRHH','rrhh_trabajadores',p_id_trabajador::VARCHAR,
   jsonb_build_object('tipo','CESE','idTrabajador',p_id_trabajador,
      'idHistorial',v_id_historial,'fechaCese',p_fecha_cese),
   'RRHH_CESE_'||v_id_historial||'_'||u.id_usuario,
   p_id_actor
 FROM public.seg_usuarios u
 JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
 JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo AND r.codigo='ADMINISTRADOR'
 JOIN public.cfg_estados_usuario eu ON eu.id_estado_usuario=u.id_estado_usuario
 WHERE eu.codigo='ACTIVO' AND eu.permite_acceso=TRUE
 ON CONFLICT (clave_deduplicacion) DO NOTHING;

 GET DIAGNOSTICS v_notificaciones=ROW_COUNT;

 PERFORM public.sp_registrar_auditoria(
  p_id_actor,'RRHH'::VARCHAR,'CESAR'::VARCHAR,
  'rrhh_trabajadores'::VARCHAR,p_id_trabajador::VARCHAR,
  'EXITOSO'::VARCHAR,'Cese laboral aplicado y comunicado al Administrador.'::VARCHAR,
  jsonb_build_object('fechaCese',p_fecha_cese,'idHistorial',v_id_historial)
 );

 p_resultado:=jsonb_build_object('idTrabajador',p_id_trabajador,
   'estadoLaboral','CESADO','fechaCese',p_fecha_cese,
   'notificacionesAdministradores',v_notificaciones);
 p_estado:='OK';
 p_mensaje:='Cese aplicado y administrador notificado.';
END
$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_programar_suspension(IN p_id_actor bigint, IN p_id_trabajador bigint, IN p_fecha_inicio timestamp with time zone, IN p_fecha_fin timestamp with time zone, IN p_motivo text, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_t public.rrhh_trabajadores%ROWTYPE;
    v_estado_actual TEXT;
    v_estado_suspendido INTEGER;
    v_id_suspension BIGINT;
    v_id_usuario BIGINT;
    v_usuario_activo BOOLEAN := FALSE;
    v_inicio TIMESTAMPTZ;
    v_estado_suspension VARCHAR(20);
BEGIN
    p_resultado := NULL;
    p_estado := 'DATOS_INVALIDOS';
    p_mensaje := 'Solicitud de suspensión inválida.';

    IF p_id_actor IS NULL OR p_id_trabajador IS NULL OR p_id_trabajador<=0
       OR NOT COALESCE(public.fn_usuario_tiene_permiso_seguridad(p_id_actor,'hr.edit'),FALSE)
    THEN
        p_estado := 'DENEGADO';
        p_mensaje := 'No tiene autorización para suspender trabajadores.';
        RETURN;
    END IF;

    v_inicio := COALESCE(p_fecha_inicio,NOW());
    IF p_fecha_fin IS NULL OR p_fecha_fin <= NOW()
       OR p_fecha_fin <= v_inicio OR v_inicio < NOW() - INTERVAL '5 minutes'
       OR LENGTH(COALESCE(BTRIM(p_motivo),'')) NOT BETWEEN 10 AND 1000
    THEN
        p_estado := 'DATOS_INVALIDOS';
        p_mensaje := 'Indique inicio, fin futuros y motivo de 10 a 1000 caracteres.';
        RETURN;
    END IF;

    SELECT * INTO v_t
    FROM public.rrhh_trabajadores
    WHERE id_trabajador=p_id_trabajador FOR UPDATE;
    IF NOT FOUND THEN
        p_estado := 'NO_ENCONTRADO';
        p_mensaje := 'Trabajador no encontrado.';
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.rrhh_cargos c
        WHERE c.id_cargo=v_t.id_cargo AND c.codigo='GERENTE_GENERAL'
    ) OR EXISTS (
        SELECT 1 FROM public.seg_usuarios u
        JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
        JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo
        WHERE u.id_persona=v_t.id_persona AND r.codigo='GERENCIA'
    ) OR NOT COALESCE(public.fn_seguridad_puede_bloquear_persona(
        p_id_actor,v_t.id_persona),FALSE)
    THEN
        p_estado := 'USUARIO_PROTEGIDO';
        p_mensaje := 'No está autorizado para suspender a este trabajador.';
        RETURN;
    END IF;

    SELECT e.codigo INTO v_estado_actual
    FROM public.cfg_estados_trabajador e
    WHERE e.id_estado_trabajador=v_t.id_estado_trabajador AND e.activo=TRUE;
    IF v_estado_actual IS DISTINCT FROM 'ACTIVO' THEN
        p_estado := 'ESTADO_INVALIDO';
        p_mensaje := 'Solo se puede suspender un trabajador ACTIVO.';
        RETURN;
    END IF;

    IF EXISTS(
        SELECT 1 FROM public.rrhh_suspensiones_laborales s
        WHERE s.id_trabajador=p_id_trabajador
          AND s.estado IN ('PROGRAMADA','VIGENTE')
    ) THEN
        p_estado := 'SUSPENSION_PENDIENTE';
        p_mensaje := 'Ya existe una suspensión programada o vigente.';
        RETURN;
    END IF;

    SELECT u.id_usuario, eu.codigo='ACTIVO'
    INTO v_id_usuario,v_usuario_activo
    FROM public.seg_usuarios u
    JOIN public.cfg_estados_usuario eu ON eu.id_estado_usuario=u.id_estado_usuario
    WHERE u.id_persona=v_t.id_persona;

    v_estado_suspension := CASE WHEN v_inicio>NOW() THEN 'PROGRAMADA' ELSE 'VIGENTE' END;

    INSERT INTO public.rrhh_suspensiones_laborales(
       id_trabajador,id_usuario_asociado,id_usuario_solicitante,
       fecha_inicio,fecha_fin,motivo,estado,usuario_activo_al_inicio,
       fecha_aplicacion
    )
    VALUES(
       p_id_trabajador,v_id_usuario,p_id_actor,
       v_inicio,p_fecha_fin,BTRIM(p_motivo),v_estado_suspension,
       COALESCE(v_usuario_activo,FALSE),
       CASE WHEN v_estado_suspension='VIGENTE' THEN NOW() ELSE NULL END
    )
    RETURNING id_suspension INTO v_id_suspension;

    IF v_estado_suspension='VIGENTE' THEN
        SELECT id_estado_trabajador INTO v_estado_suspendido
        FROM public.cfg_estados_trabajador
        WHERE codigo='SUSPENDIDO' AND activo=TRUE;
        IF v_estado_suspendido IS NULL THEN
            RAISE EXCEPTION 'Falta catálogo SUSPENDIDO';
        END IF;

        UPDATE public.rrhh_trabajadores
        SET id_estado_trabajador=v_estado_suspendido
        WHERE id_trabajador=p_id_trabajador;
    END IF;

    PERFORM public.sp_registrar_auditoria(
       p_id_actor,'RRHH'::VARCHAR,'CREAR'::VARCHAR,
       'rrhh_suspensiones_laborales'::VARCHAR,v_id_suspension::VARCHAR,
       'EXITOSO'::VARCHAR,'Suspensión laboral registrada.'::VARCHAR,
       jsonb_build_object('idTrabajador',p_id_trabajador,
          'fechaInicio',v_inicio,'fechaFin',p_fecha_fin,
          'estado',v_estado_suspension)
    );

    p_resultado := jsonb_build_object(
       'idSuspension',v_id_suspension,'idTrabajador',p_id_trabajador,
       'estado',v_estado_suspension,'fechaInicio',v_inicio,'fechaFin',p_fecha_fin);
    p_estado:='OK';
    p_mensaje:='Suspensión laboral registrada correctamente.';
EXCEPTION WHEN unique_violation THEN
    p_resultado:=NULL;
    p_estado:='SUSPENSION_PENDIENTE';
    p_mensaje:='Existe otra suspensión abierta del trabajador.';
END
$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_registrar_trabajador(IN p_id_actor bigint, IN p_datos jsonb, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_personal JSONB;
    v_laboral JSONB;

    v_id_persona BIGINT;
    v_id_trabajador BIGINT;
    v_codigo_trabajador VARCHAR;

    v_id_tipo_documento INTEGER;
    v_numero_documento TEXT;
    v_solo_numerico BOOLEAN;
    v_longitud_minima INTEGER;
    v_longitud_maxima INTEGER;
    v_persona_documento BIGINT;
    v_documento_activo BOOLEAN;

    v_nombres TEXT;
    v_apellido_paterno TEXT;
    v_apellido_materno TEXT;
    v_fecha_nacimiento DATE;

    v_correo TEXT;
    v_telefono TEXT;
    v_id_email INTEGER;
    v_id_celular INTEGER;

    v_direccion TEXT;
    v_referencia TEXT;
    v_departamento TEXT;
    v_provincia TEXT;
    v_distrito TEXT;

    v_id_cargo BIGINT;
    v_id_horario BIGINT;
    v_id_vinculo INTEGER;
    v_id_estado INTEGER;
    v_fecha_ingreso DATE;
    v_observaciones TEXT;

    v_persona_existente public.core_personas%ROWTYPE;
    v_contacto_existente public.core_personas_contactos%ROWTYPE;
    v_domicilio_existente public.core_personas_direcciones%ROWTYPE;

    v_insertar_documento BOOLEAN := FALSE;
    v_insertar_email BOOLEAN := FALSE;
    v_insertar_celular BOOLEAN := FALSE;
    v_insertar_domicilio BOOLEAN := FALSE;
BEGIN
    p_resultado := NULL;

    -- 1. AUTORIZACIÓN
    IF p_id_actor IS NULL
       OR NOT public.fn_usuario_tiene_permiso_seguridad(
           p_id_actor, 'hr.create'
       )
    THEN
        p_estado := 'DENEGADO';
        p_mensaje := 'No tiene permisos para registrar trabajadores.';
        RETURN;
    END IF;

    -- 2. ESTRUCTURA DEL FORMULARIO
    IF p_datos IS NULL
       OR JSONB_TYPEOF(p_datos) <> 'object'
       OR JSONB_TYPEOF(p_datos->'informacionPersonal') IS DISTINCT FROM 'object'
       OR JSONB_TYPEOF(p_datos->'informacionLaboral') IS DISTINCT FROM 'object'
    THEN
        p_estado := 'DATOS_INVALIDOS';
        p_mensaje := 'La información personal y laboral es obligatoria.';
        RETURN;
    END IF;

    v_personal := p_datos->'informacionPersonal';
    v_laboral := p_datos->'informacionLaboral';

    v_id_persona :=
        NULLIF(BTRIM(v_personal->>'idPersona'), '')::BIGINT;

    v_id_tipo_documento :=
        NULLIF(BTRIM(v_personal->>'idTipoDocumento'), '')::INTEGER;

    v_numero_documento :=
        UPPER(NULLIF(BTRIM(v_personal->>'numeroDocumento'), ''));

    v_nombres := NULLIF(BTRIM(v_personal->>'nombres'), '');
    v_apellido_paterno :=
        NULLIF(BTRIM(v_personal->>'apellidoPaterno'), '');
    v_apellido_materno :=
        NULLIF(BTRIM(v_personal->>'apellidoMaterno'), '');

    v_fecha_nacimiento :=
        NULLIF(v_personal->>'fechaNacimiento', '')::DATE;

    v_correo :=
        LOWER(NULLIF(BTRIM(v_personal->>'correoElectronico'), ''));

    -- Correo de la identidad ya seleccionada: si el formulario no lo envia,
    -- reutilizar el correo principal activo. No se crea ni modifica el contacto.
    IF v_id_persona IS NOT NULL AND v_correo IS NULL THEN
        SELECT LOWER(BTRIM(pc.valor))
        INTO v_correo
        FROM public.core_personas_contactos pc
        JOIN public.cfg_tipos_contacto tc
          ON tc.id_tipo_contacto = pc.id_tipo_contacto
        WHERE pc.id_persona = v_id_persona
          AND tc.codigo = 'EMAIL'
          AND tc.activo = TRUE
          AND pc.activo = TRUE
          AND pc.principal = TRUE
          AND NULLIF(BTRIM(pc.valor), '') IS NOT NULL
        ORDER BY pc.id_persona_contacto DESC
        LIMIT 1;
    END IF;

    v_telefono :=
        NULLIF(BTRIM(v_personal->>'telefono'), '');

    v_direccion := NULLIF(BTRIM(v_personal->>'direccion'), '');
    v_referencia := NULLIF(BTRIM(v_personal->>'referencia'), '');
    v_departamento := NULLIF(BTRIM(v_personal->>'departamento'), '');
    v_provincia := NULLIF(BTRIM(v_personal->>'provincia'), '');
    v_distrito := NULLIF(BTRIM(v_personal->>'distrito'), '');

    v_id_cargo :=
        NULLIF(BTRIM(v_laboral->>'idCargo'), '')::BIGINT;

    v_id_horario :=
        NULLIF(BTRIM(v_laboral->>'idHorario'), '')::BIGINT;

    v_id_vinculo :=
        NULLIF(BTRIM(v_laboral->>'idTipoVinculoLaboral'), '')::INTEGER;

    v_fecha_ingreso :=
        NULLIF(v_laboral->>'fechaIngreso', '')::DATE;

    v_observaciones :=
        NULLIF(BTRIM(v_laboral->>'observaciones'), '');

    -- 3. CAMPOS OBLIGATORIOS
    IF v_id_tipo_documento IS NULL
       OR v_numero_documento IS NULL
       OR v_nombres IS NULL
       OR v_direccion IS NULL
       OR v_departamento IS NULL
       OR v_provincia IS NULL
       OR v_distrito IS NULL
       OR v_id_cargo IS NULL
       OR v_id_vinculo IS NULL
       OR v_fecha_ingreso IS NULL
    THEN
        p_estado := 'CAMPOS_OBLIGATORIOS';
        p_mensaje := 'Complete los datos obligatorios del trabajador.';
        RETURN;
    END IF;

    IF v_id_persona IS NOT NULL AND v_id_persona <= 0 THEN
        p_estado := 'PERSONA_INVALIDA';
        p_mensaje := 'El identificador de persona es inválido.';
        RETURN;
    END IF;

    -- 4. VALIDACIÓN DEL DOCUMENTO
    SELECT
        td.solo_numerico,
        td.longitud_minima,
        td.longitud_maxima
    INTO
        v_solo_numerico,
        v_longitud_minima,
        v_longitud_maxima
    FROM public.cfg_tipos_documento td
    WHERE td.id_tipo_documento = v_id_tipo_documento
      AND td.activo = TRUE;

    IF NOT FOUND THEN
        p_estado := 'TIPO_DOCUMENTO_INVALIDO';
        p_mensaje := 'El tipo de documento no está disponible.';
        RETURN;
    END IF;

    IF v_numero_documento !~ '^[A-Z0-9-]+$'
       OR LENGTH(v_numero_documento)
          < COALESCE(v_longitud_minima, 1)
       OR LENGTH(v_numero_documento)
          > COALESCE(v_longitud_maxima, 30)
       OR (
           COALESCE(v_solo_numerico, FALSE)
           AND v_numero_documento !~ '^[0-9]+$'
       )
    THEN
        p_estado := 'DOCUMENTO_INVALIDO';
        p_mensaje := 'El documento no cumple las reglas del catálogo.';
        RETURN;
    END IF;

    -- 5. VALIDACIÓN DE CONTACTOS
    IF v_correo IS NOT NULL
       AND (
           LENGTH(v_correo) > 180
           OR v_correo !~*
              '^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
       )
    THEN
        p_estado := 'EMAIL_INVALIDO';
        p_mensaje := 'El correo electrónico es inválido.';
        RETURN;
    END IF;

    IF v_telefono IS NOT NULL
       AND (
           LENGTH(v_telefono) > 25
           OR v_telefono !~ '^[+0-9() -]+$'
           OR LENGTH(
               REGEXP_REPLACE(v_telefono, '[^0-9]', '', 'g')
           ) < 6
       )
    THEN
        p_estado := 'TELEFONO_INVALIDO';
        p_mensaje := 'El teléfono tiene un formato inválido.';
        RETURN;
    END IF;

    IF v_correo IS NOT NULL THEN
        SELECT id_tipo_contacto INTO v_id_email
        FROM public.cfg_tipos_contacto
        WHERE codigo = 'EMAIL' AND activo = TRUE;

        IF v_id_email IS NULL THEN
            p_estado := 'CONFIGURACION_INVALIDA';
            p_mensaje := 'No está configurado el tipo EMAIL.';
            RETURN;
        END IF;
    END IF;

    IF v_telefono IS NOT NULL THEN
        SELECT id_tipo_contacto INTO v_id_celular
        FROM public.cfg_tipos_contacto
        WHERE codigo = 'CELULAR' AND activo = TRUE;

        IF v_id_celular IS NULL THEN
            p_estado := 'CONFIGURACION_INVALIDA';
            p_mensaje := 'No está configurado el tipo CELULAR.';
            RETURN;
        END IF;
    END IF;

    -- 6. CATÁLOGOS LABORALES
    PERFORM 1
    FROM public.rrhh_cargos c
    JOIN public.rrhh_areas a ON a.id_area = c.id_area
    WHERE c.id_cargo = v_id_cargo
      AND c.activo = TRUE
      AND a.activo = TRUE;

    IF NOT FOUND THEN
        p_estado := 'CARGO_INVALIDO';
        p_mensaje := 'El cargo o su área no están activos.';
        RETURN;
    END IF;

    IF v_id_horario IS NOT NULL THEN
        PERFORM 1
        FROM public.rrhh_horarios
        WHERE id_horario = v_id_horario
          AND activo = TRUE;

        IF NOT FOUND THEN
            p_estado := 'HORARIO_INVALIDO';
            p_mensaje := 'El horario seleccionado no está disponible.';
            RETURN;
        END IF;
    END IF;

    PERFORM 1
    FROM public.cfg_tipos_vinculo_laboral
    WHERE id_tipo_vinculo_laboral = v_id_vinculo
      AND activo = TRUE;

    IF NOT FOUND THEN
        p_estado := 'VINCULO_INVALIDO';
        p_mensaje := 'El vínculo laboral no está disponible.';
        RETURN;
    END IF;

    SELECT id_estado_trabajador INTO v_id_estado
    FROM public.cfg_estados_trabajador
    WHERE codigo = 'ACTIVO'
      AND activo = TRUE;

    IF v_id_estado IS NULL THEN
        p_estado := 'CONFIGURACION_INVALIDA';
        p_mensaje := 'No existe el estado inicial ACTIVO.';
        RETURN;
    END IF;

    -- 7. IDENTIFICACIÓN DOCUMENTAL GLOBAL
    SELECT d.id_persona, d.activo
    INTO v_persona_documento, v_documento_activo
    FROM public.core_personas_documentos d
    WHERE d.id_tipo_documento = v_id_tipo_documento
      AND UPPER(BTRIM(d.numero_documento)) = v_numero_documento
    ORDER BY d.id_persona_documento DESC
    LIMIT 1;

    IF v_persona_documento IS NOT NULL THEN
        IF v_id_persona IS NULL THEN
            p_resultado := JSONB_BUILD_OBJECT(
                'idPersona', v_persona_documento
            );
            p_estado := 'REQUIERE_IDENTIFICACION';
            p_mensaje :=
                'El documento ya existe. Seleccione y confirme la persona.';
            RETURN;
        END IF;

        IF v_persona_documento <> v_id_persona THEN
            p_estado := 'DOCUMENTO_EN_USO';
            p_mensaje :=
                'El documento pertenece a otra persona.';
            RETURN;
        END IF;

        IF NOT COALESCE(v_documento_activo, FALSE) THEN
            p_estado := 'DOCUMENTO_INACTIVO';
            p_mensaje :=
                'El documento existente requiere revisión.';
            RETURN;
        END IF;
    END IF;

    -- 8. IDENTIFICACIÓN POR CORREO
    -- Un correo ajeno ACTIVO impide una NUEVA vinculacion. Los contactos
    -- inactivos conservan el historial, pero no bloquean la reutilizacion.
    -- Excepcion segura: si el correo ya es el principal ACTIVO de la persona
    -- seleccionada, RRHH solo enlaza su expediente; NO crea otro contacto.
    -- Las asociaciones activas compartidas preexistentes quedan pendientes
    -- de saneamiento; aqui NO se borran ni se validan como identidad unica.
    IF v_correo IS NOT NULL THEN
        IF EXISTS (
            SELECT 1
            FROM public.core_personas_contactos pc
            WHERE pc.id_tipo_contacto = v_id_email
              AND pc.activo = TRUE
              AND LOWER(BTRIM(pc.valor)) = v_correo
              AND (
                  v_id_persona IS NULL
                  OR pc.id_persona <> v_id_persona
              )
        ) AND NOT (
            v_id_persona IS NOT NULL
            AND EXISTS (
                SELECT 1
                FROM public.core_personas_contactos propio
                WHERE propio.id_persona = v_id_persona
                  AND propio.id_tipo_contacto = v_id_email
                  AND propio.activo = TRUE
                  AND propio.principal = TRUE
                  AND LOWER(BTRIM(propio.valor)) = v_correo
            )
        ) THEN
            p_estado :=
                CASE
                    WHEN v_id_persona IS NULL
                    THEN 'REQUIERE_IDENTIFICACION'
                    ELSE 'EMAIL_EN_USO'
                END;
            p_mensaje :=
                'El correo activo pertenece a otra persona; revise su titular.';
            RETURN;
        END IF;
    END IF;

    -- 9. VALIDAR LA PERSONA SELECCIONADA
    IF v_id_persona IS NOT NULL THEN
        SELECT *
        INTO v_persona_existente
        FROM public.core_personas
        WHERE id_persona = v_id_persona
          AND activo = TRUE
        FOR UPDATE;

        IF NOT FOUND THEN
            p_estado := 'PERSONA_INVALIDA';
            p_mensaje := 'La persona no existe o está inactiva.';
            RETURN;
        END IF;

        IF UPPER(BTRIM(v_persona_existente.nombres))
              IS DISTINCT FROM UPPER(v_nombres)
           OR (
               v_apellido_paterno IS NOT NULL
               AND UPPER(BTRIM(v_persona_existente.apellido_paterno))
                   IS DISTINCT FROM UPPER(v_apellido_paterno)
           )
           OR (
               v_apellido_materno IS NOT NULL
               AND UPPER(BTRIM(v_persona_existente.apellido_materno))
                   IS DISTINCT FROM UPPER(v_apellido_materno)
           )
           OR (
               v_fecha_nacimiento IS NOT NULL
               AND v_persona_existente.fecha_nacimiento IS NOT NULL
               AND v_fecha_nacimiento
                   <> v_persona_existente.fecha_nacimiento
           )
        THEN
            p_estado := 'PERSONA_NO_COINCIDE';
            p_mensaje :=
                'Los datos personales no coinciden con el registro existente.';
            RETURN;
        END IF;

        IF EXISTS (
            SELECT 1
            FROM public.rrhh_trabajadores
            WHERE id_persona = v_id_persona
        ) THEN
            p_estado := 'TRABAJADOR_EXISTENTE';
            p_mensaje :=
                'La persona ya tiene un expediente de trabajador.';
            RETURN;
        END IF;

        IF EXISTS (
            SELECT 1
            FROM public.core_personas_documentos d
            WHERE d.id_persona = v_id_persona
              AND d.id_tipo_documento = v_id_tipo_documento
              AND UPPER(BTRIM(d.numero_documento))
                  <> v_numero_documento
        ) THEN
            p_estado := 'DOCUMENTO_NO_COINCIDE';
            p_mensaje :=
                'La persona tiene otro documento de ese tipo.';
            RETURN;
        END IF;
    END IF;

    v_insertar_documento := v_persona_documento IS NULL;

    -- 10. REVISAR CONTACTOS EXISTENTES
    IF v_id_persona IS NOT NULL AND v_correo IS NOT NULL THEN
        SELECT *
        INTO v_contacto_existente
        FROM public.core_personas_contactos
        WHERE id_persona = v_id_persona
          AND id_tipo_contacto = v_id_email
        ORDER BY
            activo DESC,
            principal DESC,
            id_persona_contacto DESC
        LIMIT 1;

        IF FOUND THEN
            IF NOT COALESCE(v_contacto_existente.activo, FALSE)
               OR LOWER(BTRIM(v_contacto_existente.valor))
                  <> v_correo
            THEN
                p_estado := 'CONTACTO_NO_COINCIDE';
                p_mensaje :=
                    'El correo existente requiere revisión.';
                RETURN;
            END IF;
        ELSE
            v_insertar_email := TRUE;
        END IF;
    ELSIF v_correo IS NOT NULL THEN
        v_insertar_email := TRUE;
    END IF;

    IF v_id_persona IS NOT NULL AND v_telefono IS NOT NULL THEN
        SELECT *
        INTO v_contacto_existente
        FROM public.core_personas_contactos
        WHERE id_persona = v_id_persona
          AND id_tipo_contacto = v_id_celular
        ORDER BY
            activo DESC,
            principal DESC,
            id_persona_contacto DESC
        LIMIT 1;

        IF FOUND THEN
            IF NOT COALESCE(v_contacto_existente.activo, FALSE)
               OR REGEXP_REPLACE(
                    v_contacto_existente.valor, '[ ()-]', '', 'g'
                  )
                  <> REGEXP_REPLACE(
                    v_telefono, '[ ()-]', '', 'g'
                  )
            THEN
                p_estado := 'CONTACTO_NO_COINCIDE';
                p_mensaje :=
                    'El celular existente requiere revisión.';
                RETURN;
            END IF;
        ELSE
            v_insertar_celular := TRUE;
        END IF;
    ELSIF v_telefono IS NOT NULL THEN
        v_insertar_celular := TRUE;
    END IF;

    -- 11. REVISAR DOMICILIO EXISTENTE
    IF v_id_persona IS NOT NULL THEN
        SELECT *
        INTO v_domicilio_existente
        FROM public.core_personas_direcciones
        WHERE id_persona = v_id_persona
          AND UPPER(BTRIM(tipo)) = 'DOMICILIO'
        ORDER BY
            activo DESC,
            principal DESC,
            id_persona_direccion DESC
        LIMIT 1;

        IF FOUND THEN
            IF NOT COALESCE(v_domicilio_existente.activo, FALSE)
               OR UPPER(BTRIM(v_domicilio_existente.direccion))
                   IS DISTINCT FROM UPPER(v_direccion)
               OR UPPER(BTRIM(v_domicilio_existente.departamento))
                   IS DISTINCT FROM UPPER(v_departamento)
               OR UPPER(BTRIM(v_domicilio_existente.provincia))
                   IS DISTINCT FROM UPPER(v_provincia)
               OR UPPER(BTRIM(v_domicilio_existente.distrito))
                   IS DISTINCT FROM UPPER(v_distrito)
            THEN
                p_estado := 'DOMICILIO_NO_COINCIDE';
                p_mensaje :=
                    'El domicilio existente requiere revisión.';
                RETURN;
            END IF;
        ELSE
            v_insertar_domicilio := TRUE;
        END IF;
    ELSE
        v_insertar_domicilio := TRUE;
    END IF;

    -- 12. INICIO DE ESCRITURAS
    -- Cualquier error SQL capturado por el bloque EXCEPTION
    -- revierte las escrituras de este procedimiento.

    IF v_id_persona IS NULL THEN
        INSERT INTO public.core_personas (
            nombres,
            apellido_paterno,
            apellido_materno,
            fecha_nacimiento,
            activo
        )
        VALUES (
            v_nombres,
            v_apellido_paterno,
            v_apellido_materno,
            v_fecha_nacimiento,
            TRUE
        )
        RETURNING id_persona INTO v_id_persona;
    END IF;

    IF v_insertar_documento THEN
        INSERT INTO public.core_personas_documentos (
            id_persona,
            id_tipo_documento,
            numero_documento,
            principal,
            verificado,
            activo
        )
        VALUES (
            v_id_persona,
            v_id_tipo_documento,
            v_numero_documento,
            TRUE,
            FALSE,
            TRUE
        );
    END IF;

    IF v_insertar_email THEN
        INSERT INTO public.core_personas_contactos (
            id_persona,
            id_tipo_contacto,
            valor,
            principal,
            verificado,
            permite_notificaciones,
            activo
        )
        VALUES (
            v_id_persona,
            v_id_email,
            v_correo,
            TRUE,
            FALSE,
            FALSE,
            TRUE
        );
    END IF;

    IF v_insertar_celular THEN
        INSERT INTO public.core_personas_contactos (
            id_persona,
            id_tipo_contacto,
            valor,
            principal,
            verificado,
            permite_notificaciones,
            activo
        )
        VALUES (
            v_id_persona,
            v_id_celular,
            v_telefono,
            TRUE,
            FALSE,
            FALSE,
            TRUE
        );
    END IF;

    IF v_insertar_domicilio THEN
        INSERT INTO public.core_personas_direcciones (
            id_persona,
            tipo,
            direccion,
            referencia,
            departamento,
            provincia,
            distrito,
            pais,
            principal,
            activo
        )
        VALUES (
            v_id_persona,
            'DOMICILIO',
            v_direccion,
            v_referencia,
            v_departamento,
            v_provincia,
            v_distrito,
            'Perú',
            TRUE,
            TRUE
        );
    END IF;

    -- 13. EXPEDIENTE LABORAL
    INSERT INTO public.rrhh_trabajadores (
        id_persona,
        id_cargo,
        id_horario,
        id_estado_trabajador,
        id_tipo_vinculo_laboral,
        fecha_ingreso,
        observaciones
    )
    VALUES (
        v_id_persona,
        v_id_cargo,
        v_id_horario,
        v_id_estado,
        v_id_vinculo,
        v_fecha_ingreso,
        v_observaciones
    )
    RETURNING id_trabajador, codigo
    INTO v_id_trabajador, v_codigo_trabajador;

    p_resultado := JSONB_BUILD_OBJECT(
        'idTrabajador', v_id_trabajador,
        'idPersona', v_id_persona,
        'codigo', v_codigo_trabajador
    );

    p_estado := 'OK';
    p_mensaje := 'Trabajador registrado correctamente.';

EXCEPTION
    WHEN unique_violation THEN
        p_resultado := NULL;
        p_estado := 'CONFLICTO_UNICIDAD';
        p_mensaje :=
            'Existe un registro que impide duplicar la información.';

    WHEN invalid_text_representation
      OR invalid_datetime_format
      OR datetime_field_overflow
      OR numeric_value_out_of_range
    THEN
        p_resultado := NULL;
        p_estado := 'DATOS_INVALIDOS';
        p_mensaje :=
            'Uno o más identificadores o fechas tienen formato inválido.';
END;
$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_resolver_reincorporacion(IN p_id_actor bigint, IN p_id_solicitud bigint, IN p_decision character varying, IN p_motivo_resolucion text, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
 v_s public.rrhh_solicitudes_reincorporacion%ROWTYPE;
 v_t public.rrhh_trabajadores%ROWTYPE;
 v_decision TEXT;
 v_motivo TEXT;
 v_estado_actual TEXT;
 v_estado_activo INTEGER;
 v_id_historial BIGINT;
 v_estado_usuario TEXT;
BEGIN
 p_resultado:=NULL;p_estado:='DATOS_INVALIDOS';
 p_mensaje:='Datos de resolución inválidos.';
 v_decision:=UPPER(NULLIF(BTRIM(p_decision),''));
 v_motivo:=NULLIF(BTRIM(p_motivo_resolucion),'');
 IF p_id_actor IS NULL OR p_id_solicitud IS NULL OR p_id_solicitud<=0
    OR v_decision IS NULL OR v_decision NOT IN ('APROBAR','RECHAZAR')
 THEN RETURN;END IF;

 IF NOT COALESCE(public.fn_usuario_tiene_permiso_seguridad(p_id_actor,'hr.approve'),FALSE)
   OR NOT EXISTS(
     SELECT 1 FROM public.seg_usuarios u
     JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
     JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo AND r.codigo='ADMINISTRADOR'
     JOIN public.cfg_estados_usuario e ON e.id_estado_usuario=u.id_estado_usuario
     WHERE u.id_usuario=p_id_actor AND e.codigo='ACTIVO' AND e.permite_acceso
   )
 THEN
   p_estado:='DENEGADO';
   p_mensaje:='Solo el Administrador activo puede resolver reincorporaciones.';
   RETURN;
 END IF;

 IF LENGTH(COALESCE(v_motivo,''))>1000
   OR (v_decision='RECHAZAR' AND LENGTH(COALESCE(v_motivo,''))<10)
 THEN
   p_estado:='MOTIVO_INVALIDO';
   p_mensaje:='El rechazo exige justificación de 10 a 1000 caracteres.';
   RETURN;
 END IF;

 SELECT * INTO v_s FROM public.rrhh_solicitudes_reincorporacion
 WHERE id_solicitud=p_id_solicitud FOR UPDATE;
 IF NOT FOUND THEN
   p_estado:='NO_ENCONTRADA';p_mensaje:='Solicitud no encontrada.';RETURN;
 END IF;
 IF v_s.estado <> 'PENDIENTE' THEN
   p_estado:='SOLICITUD_RESUELTA';p_mensaje:='La solicitud ya fue resuelta.';RETURN;
 END IF;
 IF v_s.id_usuario_solicitante=p_id_actor THEN
   p_estado:='AUTOAPROBACION_DENEGADA';
   p_mensaje:='No puede resolver una solicitud presentada por usted.';
   RETURN;
 END IF;

 SELECT * INTO v_t FROM public.rrhh_trabajadores
 WHERE id_trabajador=v_s.id_trabajador FOR UPDATE;
 IF NOT FOUND THEN
   p_estado:='NO_ENCONTRADO';p_mensaje:='El trabajador no existe.';RETURN;
 END IF;

 -- El Administrador no puede aprobar la reincorporación de su propia cuenta.
 IF EXISTS(SELECT 1 FROM public.seg_usuarios u
   WHERE u.id_usuario=p_id_actor AND u.id_persona=v_t.id_persona) THEN
   p_estado:='AUTOAPROBACION_DENEGADA';
   p_mensaje:='No puede reactivar su propio expediente laboral.';
   RETURN;
 END IF;

 IF EXISTS(SELECT 1 FROM public.rrhh_cargos c
     WHERE c.id_cargo=v_t.id_cargo AND c.codigo='GERENTE_GENERAL')
   OR EXISTS(SELECT 1 FROM public.seg_usuarios u
     JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
     JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo
     WHERE u.id_persona=v_t.id_persona AND r.codigo='GERENCIA')
 THEN
   p_estado:='USUARIO_PROTEGIDO';p_mensaje:='Gerencia no puede reincorporarse por este flujo.';RETURN;
 END IF;

 SELECT codigo INTO v_estado_actual
 FROM public.cfg_estados_trabajador
 WHERE id_estado_trabajador=v_t.id_estado_trabajador;
 IF v_estado_actual IS DISTINCT FROM 'CESADO' OR v_t.fecha_cese IS NULL THEN
   p_estado:='ESTADO_INVALIDO';
   p_mensaje:='El trabajador ya no está cesado o no tiene fecha de cese.';
   RETURN;
 END IF;

 IF v_decision='APROBAR' THEN
   IF v_s.nueva_fecha_ingreso<=v_t.fecha_cese
     OR v_s.nueva_fecha_ingreso>CURRENT_DATE THEN
     p_estado:='FECHAS_INVALIDAS';
     p_mensaje:='La reincorporación solo puede aprobarse en o después de su fecha de ingreso, posterior al cese.';
     RETURN;
   END IF;
   SELECT id_estado_trabajador INTO v_estado_activo
   FROM public.cfg_estados_trabajador WHERE codigo='ACTIVO' AND activo=TRUE;
   IF v_estado_activo IS NULL THEN
     p_estado:='CONFIGURACION_INVALIDA';p_mensaje:='Estado ACTIVO no disponible.';RETURN;
   END IF;

   UPDATE public.rrhh_trabajadores
   SET id_estado_trabajador=v_estado_activo,
       fecha_ingreso=v_s.nueva_fecha_ingreso,
       fecha_cese=NULL
   WHERE id_trabajador=v_s.id_trabajador;

   INSERT INTO public.rrhh_trabajadores_historial_laboral(
      id_trabajador,id_estado_anterior,id_estado_nuevo,
      fecha_ingreso_anterior,fecha_ingreso_nueva,
      fecha_cese_anterior,fecha_cese_nueva,motivo,id_usuario_actor
   )
   VALUES(
      v_t.id_trabajador,v_t.id_estado_trabajador,v_estado_activo,
      v_t.fecha_ingreso,v_s.nueva_fecha_ingreso,
      v_t.fecha_cese,NULL,
      'Reincorporación aprobada. '||COALESCE(v_motivo,'Solicitud '||v_s.id_solicitud),
      p_id_actor
   ) RETURNING id_historial INTO v_id_historial;

   UPDATE public.rrhh_solicitudes_reincorporacion
   SET estado='APROBADA',id_usuario_resolutor=p_id_actor,
       fecha_resolucion=NOW(),motivo_resolucion=v_motivo,
       fecha_actualizacion=NOW()
   WHERE id_solicitud=p_id_solicitud;

 ELSE
   UPDATE public.rrhh_solicitudes_reincorporacion
   SET estado='RECHAZADA',id_usuario_resolutor=p_id_actor,
       fecha_resolucion=NOW(),motivo_resolucion=v_motivo,
       fecha_actualizacion=NOW()
   WHERE id_solicitud=p_id_solicitud;
 END IF;

 SELECT eu.codigo INTO v_estado_usuario
 FROM public.seg_usuarios u
 JOIN public.cfg_estados_usuario eu ON eu.id_estado_usuario=u.id_estado_usuario
 WHERE u.id_persona=v_t.id_persona;

 PERFORM public.sp_registrar_auditoria(
   p_id_actor,'RRHH'::VARCHAR,v_decision::VARCHAR,
   'rrhh_solicitudes_reincorporacion'::VARCHAR,p_id_solicitud::VARCHAR,
   'EXITOSO'::VARCHAR,'Resolución administrativa de reincorporación.'::VARCHAR,
   jsonb_build_object('idTrabajador',v_s.id_trabajador,'decision',v_decision,
      'fechaIngreso',v_s.nueva_fecha_ingreso,
      'estadoUsuario',v_estado_usuario)
 );

 p_resultado:=jsonb_build_object('idSolicitud',p_id_solicitud,
   'idTrabajador',v_s.id_trabajador,
   'estado',CASE WHEN v_decision='APROBAR' THEN 'APROBADA' ELSE 'RECHAZADA' END,
   'estadoLaboral',CASE WHEN v_decision='APROBAR' THEN 'ACTIVO' ELSE 'CESADO' END,
   'estadoUsuario',v_estado_usuario,
   'requiereRevisionUsuario',v_decision='APROBAR' AND v_estado_usuario IS DISTINCT FROM 'ACTIVO');
 p_estado:='OK';
 p_mensaje:=CASE WHEN v_decision='APROBAR'
   THEN 'Reincorporación aplicada; verificar estado resultante del usuario.'
   ELSE 'Reincorporación rechazada. El trabajador continúa CESADO.' END;
END
$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_solicitar_cambio_correo(IN p_id_actor bigint, IN p_id_trabajador bigint, IN p_correo_nuevo text, IN p_motivo text, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_persona bigint;
    v_correo text;
    v_motivo text;
    v_email_tipo integer;
    v_id_contacto bigint;
    v_correo_actual text;
    v_id_solicitud bigint;
BEGIN
    p_resultado := NULL;

    -- 1. Validar permisos del actor
    IF p_id_actor IS NULL OR NOT public.fn_usuario_tiene_permiso_seguridad(p_id_actor, 'hr.edit') THEN
        p_estado := 'DENEGADO';
        p_mensaje := 'No tiene permisos para solicitar cambio de correo.';
        RETURN;
    END IF;

    -- 2. Validar existencia del trabajador
    SELECT id_persona INTO v_persona
    FROM public.rrhh_trabajadores
    WHERE id_trabajador = p_id_trabajador
    FOR UPDATE;

    IF NOT FOUND THEN
        p_estado := 'NO_ENCONTRADO';
        p_mensaje := 'Trabajador no encontrado.';
        RETURN;
    END IF;

    -- 3. Proteccion para cuenta del Gerente General
    IF (
        EXISTS (
            SELECT 1 FROM public.rrhh_trabajadores t
            JOIN public.rrhh_cargos c ON c.id_cargo = t.id_cargo
            WHERE t.id_trabajador = p_id_trabajador AND c.codigo = 'GERENTE_GENERAL'
        )
        OR EXISTS (
            SELECT 1 FROM public.seg_usuarios u
            JOIN public.seg_usuarios_roles ur ON ur.id_usuario = u.id_usuario AND ur.activo
            JOIN public.seg_roles r ON r.id_rol = ur.id_rol AND r.activo
            WHERE u.id_persona = v_persona AND r.codigo = 'GERENCIA'
        )
    ) THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.seg_usuarios u
            WHERE u.id_usuario = p_id_actor AND u.id_persona = v_persona
        ) THEN
            p_estado := 'USUARIO_PROTEGIDO';
            p_mensaje := 'RRHH no puede cambiar el correo del Gerente General.';
            RETURN;
        END IF;
    END IF;

    -- 4. Validar formato de correo nuevo
    SELECT id_tipo_contacto INTO v_email_tipo
    FROM public.cfg_tipos_contacto
    WHERE codigo = 'EMAIL' AND activo;

    IF v_email_tipo IS NULL THEN
        p_estado := 'CONFIGURACION_INVALIDA';
        p_mensaje := 'Tipo de contacto EMAIL no configurado.';
        RETURN;
    END IF;

    v_correo := LOWER(NULLIF(BTRIM(p_correo_nuevo), ''));
    IF v_correo IS NULL OR LENGTH(v_correo) > 180
       OR v_correo !~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'
    THEN
        p_estado := 'DATOS_INVALIDOS';
        p_mensaje := 'El formato del correo electronico es invalido.';
        RETURN;
    END IF;

    -- 5. Validar motivo (10 a 1000 caracteres)
    v_motivo := NULLIF(BTRIM(p_motivo), '');
    IF v_motivo IS NULL OR LENGTH(v_motivo) < 10 OR LENGTH(v_motivo) > 1000 THEN
        p_estado := 'MOTIVO_INVALIDO';
        p_mensaje := 'El motivo debe tener entre 10 y 1000 caracteres.';
        RETURN;
    END IF;

    -- 6. Unicidad respecto a otras personas
    IF EXISTS (
        SELECT 1 FROM public.core_personas_contactos
        WHERE id_tipo_contacto = v_email_tipo
          AND activo = TRUE
          AND LOWER(BTRIM(valor)) = v_correo
          AND id_persona <> v_persona
    ) THEN
        p_estado := 'EMAIL_EN_USO';
        p_mensaje := 'El correo electronico ya esta registrado por otra persona.';
        RETURN;
    END IF;

    -- 7. Obtener contacto actual (si existe, verificado o no)
    SELECT id_persona_contacto, valor
    INTO v_id_contacto, v_correo_actual
    FROM public.core_personas_contactos
    WHERE id_persona = v_persona
      AND id_tipo_contacto = v_email_tipo
      AND activo = TRUE
    ORDER BY principal DESC, id_persona_contacto DESC
    LIMIT 1;

    -- Validar si coincide con el correo actual
    IF v_correo_actual IS NOT NULL AND LOWER(BTRIM(v_correo_actual)) = v_correo THEN
        p_estado := 'SIN_CAMBIOS';
        p_mensaje := 'El correo ingresado ya es el actual del trabajador.';
        RETURN;
    END IF;

    -- El expediente debe contar con un contacto actual para anclar la corrección.
    IF v_id_contacto IS NULL OR v_correo_actual IS NULL THEN
        p_estado := 'CONTACTO_NO_REGISTRADO';
        p_mensaje := 'Registra primero un correo inicial para este trabajador.';
        RETURN;
    END IF;

    -- 8. Prevenir solicitudes pendientes duplicadas
    IF EXISTS (
        SELECT 1 FROM public.core_solicitudes_correccion_identidad
        WHERE id_persona = v_persona
          AND tipo_dato = 'CONTACTO'
          AND estado = 'PENDIENTE'
    ) THEN
        p_estado := 'SOLICITUD_PENDIENTE';
        p_mensaje := 'Ya existe una solicitud de cambio de correo pendiente para este trabajador.';
        RETURN;
    END IF;

    -- 9. Registrar la solicitud PENDIENTE (sin token ni enlace aun)
    INSERT INTO public.core_solicitudes_correccion_identidad (
        id_persona,
        modulo_origen,
        tipo_dato,
        id_persona_contacto,
        valor_anterior,
        valor_propuesto,
        motivo,
        id_usuario_solicitante,
        estado,
        fecha_solicitud
    ) VALUES (
        v_persona,
        'RRHH',
        'CONTACTO',
        v_id_contacto,
        v_correo_actual,
        v_correo,
        v_motivo,
        p_id_actor,
        'PENDIENTE',
        NOW()
    ) RETURNING id_solicitud INTO v_id_solicitud;

    -- 10. Auditoria
    PERFORM public.sp_registrar_auditoria(
        p_id_actor,
        'RRHH'::VARCHAR,
        'CREAR'::VARCHAR,
        'core_solicitudes_correccion_identidad'::VARCHAR,
        v_id_solicitud::VARCHAR,
        'EXITOSO'::VARCHAR,
        'Solicitud de cambio de correo registrada, pendiente de aprobacion.'::VARCHAR,
        JSONB_BUILD_OBJECT('idPersona', v_persona, 'correoPropuesto', v_correo)
    );

    p_resultado := JSONB_BUILD_OBJECT(
        'idSolicitud', v_id_solicitud,
        'idPersona', v_persona,
        'correoPropuesto', v_correo,
        'estado', 'PENDIENTE'
    );
    p_estado := 'OK';
    p_mensaje := 'Solicitud de cambio de correo registrada correctamente. Pendiente de aprobacion.';
EXCEPTION
    WHEN unique_violation THEN
        p_resultado := NULL;
        p_estado := 'CONFLICTO_UNICIDAD';
        p_mensaje := 'Conflicto de unicidad con una solicitud existente.';
END;
$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_solicitar_correccion_documento(IN p_id_actor bigint, IN p_id_trabajador bigint, IN p_tipo_nuevo integer, IN p_numero_nuevo text, IN p_motivo text, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE v_t public.rrhh_trabajadores%ROWTYPE;v_d public.core_personas_documentos%ROWTYPE;
 v_num text;v_min integer;v_max integer;v_solo boolean;v_verificar integer;v_id bigint;
BEGIN
 p_resultado:=NULL;
 IF p_id_actor IS NULL OR NOT public.fn_usuario_tiene_permiso_seguridad(p_id_actor,'hr.edit')
 THEN p_estado:='DENEGADO';p_mensaje:='Sin permisos.';RETURN;END IF;
 SELECT * INTO v_t FROM public.rrhh_trabajadores WHERE id_trabajador=p_id_trabajador FOR UPDATE;
 IF NOT FOUND THEN p_estado:='NO_ENCONTRADO';p_mensaje:='Trabajador inexistente.';RETURN;END IF;
 IF (
        EXISTS (
          SELECT 1 FROM public.rrhh_cargos c
          WHERE c.id_cargo=v_t.id_cargo AND c.codigo='GERENTE_GENERAL'
        )
        OR EXISTS (
          SELECT 1 FROM public.seg_usuarios u
          JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
          JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo
          WHERE u.id_persona=v_t.id_persona AND r.codigo='GERENCIA'
        )
      ) AND NOT EXISTS (
        SELECT 1 FROM public.seg_usuarios u
        WHERE u.id_usuario=p_id_actor AND u.id_persona=v_t.id_persona
      )
      THEN
        p_estado:='USUARIO_PROTEGIDO';
        p_mensaje:='RRHH no puede solicitar correcciones para el Gerente General.';
        RETURN;
      END IF;
      IF NOT public.fn_seguridad_puede_bloquear_persona(p_id_actor,v_t.id_persona)
 THEN p_estado:='USUARIO_PROTEGIDO';p_mensaje:='Cuenta protegida.';RETURN;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.cfg_estados_trabajador
 WHERE id_estado_trabajador=v_t.id_estado_trabajador AND codigo='ACTIVO')
 THEN p_estado:='ESTADO_INVALIDO';p_mensaje:='Debe encontrarse ACTIVO.';RETURN;END IF;
 SELECT * INTO v_d FROM public.core_personas_documentos WHERE id_persona=v_t.id_persona AND principal AND activo FOR UPDATE;
 IF NOT FOUND THEN p_estado:='DOCUMENTO_INVALIDO';p_mensaje:='Documento principal inexistente.';RETURN;END IF;
 SELECT longitud_minima,longitud_maxima,solo_numerico INTO v_min,v_max,v_solo
 FROM public.cfg_tipos_documento WHERE id_tipo_documento=p_tipo_nuevo AND activo;
 IF NOT FOUND THEN p_estado:='TIPO_DOCUMENTO_INVALIDO';p_mensaje:='Tipo inexistente.';RETURN;END IF;
 v_num:=UPPER(NULLIF(BTRIM(p_numero_nuevo),''));
 IF v_num IS NULL OR v_num !~ '^[A-Z0-9-]+$'
 OR LENGTH(v_num)<COALESCE(v_min,1) OR LENGTH(v_num)>COALESCE(v_max,30)
 OR (COALESCE(v_solo,FALSE) AND v_num !~ '^[0-9]+$')
 THEN p_estado:='DOCUMENTO_INVALIDO';p_mensaje:='Número inválido.';RETURN;END IF;
 IF LENGTH(COALESCE(BTRIM(p_motivo),'')) NOT BETWEEN 10 AND 1000
 THEN p_estado:='MOTIVO_INVALIDO';p_mensaje:='Motivo de 10 a 1000 caracteres obligatorio.';RETURN;END IF;
 IF p_tipo_nuevo=v_d.id_tipo_documento AND v_num=UPPER(BTRIM(v_d.numero_documento))
 THEN p_estado:='SIN_CAMBIOS';p_mensaje:='Sin cambios.';RETURN;END IF;
 IF EXISTS(SELECT 1 FROM public.core_personas_documentos
 WHERE id_tipo_documento=p_tipo_nuevo AND UPPER(BTRIM(numero_documento))=v_num
 AND id_persona_documento<>v_d.id_persona_documento)
 THEN p_estado:='DOCUMENTO_EN_USO';p_mensaje:='Documento ocupado.';RETURN;END IF;
 IF EXISTS(SELECT 1 FROM public.core_solicitudes_correccion_identidad WHERE id_persona_documento=v_d.id_persona_documento AND estado='PENDIENTE')
 THEN p_estado:='SOLICITUD_PENDIENTE';p_mensaje:='Existe una solicitud pendiente.';RETURN;END IF;
 SELECT id_estado_trabajador INTO v_verificar FROM public.cfg_estados_trabajador WHERE codigo='EN_VERIFICACION' AND activo;
 IF v_verificar IS NULL THEN p_estado:='CONFIGURACION_INVALIDA';p_mensaje:='Estado de verificación inexistente.';RETURN;END IF;
 INSERT INTO public.core_solicitudes_correccion_identidad(
 id_persona,modulo_origen,tipo_dato,id_persona_documento,valor_anterior,
 valor_propuesto,motivo,id_usuario_solicitante,id_tipo_documento_propuesto,id_estado_trabajador_previo)
 VALUES(v_t.id_persona,'RRHH','DOCUMENTO',v_d.id_persona_documento,
 v_d.numero_documento,v_num,BTRIM(p_motivo),p_id_actor,p_tipo_nuevo,v_t.id_estado_trabajador)
 RETURNING id_solicitud INTO v_id;
 UPDATE public.rrhh_trabajadores SET id_estado_trabajador=v_verificar WHERE id_trabajador=p_id_trabajador;
 PERFORM public.sp_registrar_auditoria(p_id_actor,'RRHH'::varchar,'CREAR'::varchar,
 'core_solicitudes_correccion_identidad'::varchar,v_id::varchar,'EXITOSO'::varchar,
 'Corrección documental solicitada, evidencia obligatoria.'::varchar,
 jsonb_build_object('idPersona',v_t.id_persona,'evidenciaAdjuntada',false));
 p_resultado:=jsonb_build_object('idSolicitud',v_id,'estado','PENDIENTE');
 p_estado:='OK';p_mensaje:='Solicitud creada. Adjunte imagen de evidencia.';
EXCEPTION WHEN unique_violation THEN p_resultado:=NULL;p_estado:='CONFLICTO_UNICIDAD';p_mensaje:='Solicitud o documento duplicados.';
END;$procedure$

CREATE OR REPLACE PROCEDURE public.sp_rrhh_solicitar_reincorporacion(IN p_id_actor bigint, IN p_id_trabajador bigint, IN p_nueva_fecha_ingreso date, IN p_motivo text, OUT p_resultado jsonb, OUT p_estado character varying, OUT p_mensaje character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $procedure$
DECLARE
 v_t public.rrhh_trabajadores%ROWTYPE;
 v_estado_actual TEXT;
 v_id_solicitud BIGINT;
 v_tipo_notificacion INTEGER;
 v_nombre TEXT;
 v_notificaciones INTEGER;
BEGIN
 p_resultado:=NULL;p_estado:='DATOS_INVALIDOS';
 p_mensaje:='Solicitud de reincorporación inválida.';
 IF p_id_actor IS NULL OR p_id_trabajador IS NULL OR p_id_trabajador<=0
   OR NOT COALESCE(public.fn_usuario_tiene_permiso_seguridad(p_id_actor,'hr.edit'),FALSE)
 THEN
   p_estado:='DENEGADO';p_mensaje:='No está autorizado para solicitar reincorporaciones.'; RETURN;
 END IF;
 IF p_nueva_fecha_ingreso IS NULL
   OR LENGTH(COALESCE(BTRIM(p_motivo),'')) NOT BETWEEN 10 AND 1000
 THEN
   p_estado:='DATOS_INVALIDOS';p_mensaje:='Fecha y motivo de 10 a 1000 caracteres obligatorios.';RETURN;
 END IF;
 SELECT * INTO v_t FROM public.rrhh_trabajadores
 WHERE id_trabajador=p_id_trabajador FOR UPDATE;
 IF NOT FOUND THEN
   p_estado:='NO_ENCONTRADO';p_mensaje:='Trabajador inexistente.';RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM public.rrhh_cargos c
    WHERE c.id_cargo=v_t.id_cargo AND c.codigo='GERENTE_GENERAL')
   OR EXISTS(SELECT 1 FROM public.seg_usuarios u
    JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
    JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo
    WHERE u.id_persona=v_t.id_persona AND r.codigo='GERENCIA')
   OR NOT COALESCE(public.fn_seguridad_puede_bloquear_persona(p_id_actor,v_t.id_persona),FALSE)
 THEN
   p_estado:='USUARIO_PROTEGIDO';p_mensaje:='No se puede solicitar la reincorporación de esta cuenta protegida.';RETURN;
 END IF;
 SELECT codigo INTO v_estado_actual
 FROM public.cfg_estados_trabajador WHERE id_estado_trabajador=v_t.id_estado_trabajador;
 IF v_estado_actual IS DISTINCT FROM 'CESADO' OR v_t.fecha_cese IS NULL THEN
   p_estado:='ESTADO_INVALIDO';p_mensaje:='El trabajador debe estar CESADO con fecha de cese registrada.';RETURN;
 END IF;
 IF p_nueva_fecha_ingreso <= v_t.fecha_cese THEN
   p_estado:='FECHAS_INVALIDAS';p_mensaje:='La nueva fecha debe ser posterior al último cese.';RETURN;
 END IF;
 IF EXISTS(
   SELECT 1 FROM public.rrhh_solicitudes_reincorporacion
   WHERE id_trabajador=p_id_trabajador AND estado='PENDIENTE'
 ) THEN
   p_estado:='SOLICITUD_PENDIENTE';p_mensaje:='Ya existe una reincorporación pendiente de aprobación.';RETURN;
 END IF;

 SELECT id_tipo_notificacion INTO v_tipo_notificacion
 FROM public.cfg_tipos_notificacion WHERE codigo='GENERAL' AND activo=TRUE;
 IF v_tipo_notificacion IS NULL OR NOT EXISTS(
   SELECT 1 FROM public.seg_usuarios u
   JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
   JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo AND r.codigo='ADMINISTRADOR'
   JOIN public.cfg_estados_usuario eu ON eu.id_estado_usuario=u.id_estado_usuario
   WHERE eu.codigo='ACTIVO' AND eu.permite_acceso
 ) THEN
   p_estado:='SIN_ADMINISTRADOR';
   p_mensaje:='No hay administrador activo para recibir la solicitud.';
   RETURN;
 END IF;

 INSERT INTO public.rrhh_solicitudes_reincorporacion(
   id_trabajador,id_usuario_solicitante,nueva_fecha_ingreso,motivo
 )
 VALUES(p_id_trabajador,p_id_actor,p_nueva_fecha_ingreso,BTRIM(p_motivo))
 RETURNING id_solicitud INTO v_id_solicitud;

 SELECT CONCAT_WS(' ',p.nombres,p.apellido_paterno,p.apellido_materno)
 INTO v_nombre FROM public.core_personas p WHERE p.id_persona=v_t.id_persona;

 INSERT INTO public.not_notificaciones(
   id_persona,id_tipo_notificacion,titulo,mensaje,url_destino,
   referencia_modulo,referencia_entidad,referencia_id,
   datos_contexto,clave_deduplicacion,id_usuario_generacion
 )
 SELECT DISTINCT
   u.id_persona,v_tipo_notificacion,'Reincorporación pendiente de aprobación',
   LEFT('Se solicita reincorporar al trabajador '||v_nombre||' ('||v_t.codigo||
     ') desde el '||TO_CHAR(p_nueva_fecha_ingreso,'DD/MM/YYYY')||
     '. Revise y apruebe o rechace la solicitud.',1000),
   '/trabajadores','RRHH','rrhh_solicitudes_reincorporacion',
   v_id_solicitud::VARCHAR,
   jsonb_build_object('tipo','REINCORPORACION_PENDIENTE','idSolicitud',v_id_solicitud,
     'idTrabajador',p_id_trabajador,'fechaIngreso',p_nueva_fecha_ingreso,
     'accion','RESOLVER_REINCORPORACION'),
   'RRHH_REINCORPORACION_'||v_id_solicitud||'_'||u.id_usuario,
   p_id_actor
 FROM public.seg_usuarios u
 JOIN public.seg_usuarios_roles ur ON ur.id_usuario=u.id_usuario AND ur.activo
 JOIN public.seg_roles r ON r.id_rol=ur.id_rol AND r.activo AND r.codigo='ADMINISTRADOR'
 JOIN public.cfg_estados_usuario eu ON eu.id_estado_usuario=u.id_estado_usuario
 WHERE eu.codigo='ACTIVO' AND eu.permite_acceso=TRUE
 ON CONFLICT(clave_deduplicacion) DO NOTHING;
 GET DIAGNOSTICS v_notificaciones=ROW_COUNT;

 PERFORM public.sp_registrar_auditoria(
  p_id_actor,'RRHH'::VARCHAR,'SOLICITAR_REINCORPORACION'::VARCHAR,
  'rrhh_solicitudes_reincorporacion'::VARCHAR,v_id_solicitud::VARCHAR,
  'EXITOSO'::VARCHAR,'Solicitud de reincorporación enviada a Administración.'::VARCHAR,
  jsonb_build_object('idTrabajador',p_id_trabajador,
    'fechaIngresoPropuesta',p_nueva_fecha_ingreso)
 );

 p_resultado:=jsonb_build_object('idSolicitud',v_id_solicitud,'estado','PENDIENTE',
   'notificacionesAdministradores',v_notificaciones);
 p_estado:='OK';p_mensaje:='Solicitud registrada; el trabajador continúa CESADO hasta su aprobación.';
EXCEPTION WHEN unique_violation THEN
 p_resultado:=NULL;p_estado:='SOLICITUD_PENDIENTE';
 p_mensaje:='Ya existe una solicitud pendiente.';
END
$procedure$
